window.TTS_DATA=window.TTS_DATA||{};window.TTS_DATA[6]=[{"t": "h", "l": 0, "s": "Лекц 6. IEC 61850, дижитал дэд станц ба автоматжуулалт", "h": "<b>Лекц 6. IEC 61850, дижитал дэд станц ба автоматжуулалт</b>"}, {"t": "p", "s": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг", "h": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг"}, {"t": "p", "s": "Лекцийн зорилго. Дэд станцын автоматжуулалтын системийн (SAS) станц–бэй–процессын гурван түвшинт архитектурыг ойлгох; IEC 61850 стандартын бүтэц, өгөгдлийн загвар (физик төхөөрөмж, логик төхөөрөмж, логик зангилаа, өгөгдлийн объект ба атрибут), SCL файл ба инженерчлэлийн дарааллыг эзэмших; MMS, GOOSE, Sampled Values мессежийн ажиллах зарчим, хугацааны шаардлагыг тооцох; Ethernet сүлжээний саатал, PRP/HSR нөөцлөлийн бэлэн байдал, цаг синхрончлолын алдааны нөлөөг тоон үнэлэх; дэд станцыг диспетчерийн төвтэй холбох протокол (IEC 60870-5-104, DNP3), GOOSE-ээр блоклолт, туршилтын горимыг тайлбарлах.", "h": "<b>Лекцийн зорилго.</b> Дэд станцын автоматжуулалтын системийн (SAS) станц–бэй–процессын гурван түвшинт архитектурыг ойлгох; IEC 61850 стандартын бүтэц, өгөгдлийн загвар (физик төхөөрөмж, логик төхөөрөмж, логик зангилаа, өгөгдлийн объект ба атрибут), SCL файл ба инженерчлэлийн дарааллыг эзэмших; MMS, GOOSE, Sampled Values мессежийн ажиллах зарчим, хугацааны шаардлагыг тооцох; Ethernet сүлжээний саатал, PRP/HSR нөөцлөлийн бэлэн байдал, цаг синхрончлолын алдааны нөлөөг тоон үнэлэх; дэд станцыг диспетчерийн төвтэй холбох протокол (IEC 60870-5-104, DNP3), GOOSE-ээр блоклолт, туршилтын горимыг тайлбарлах.", "x": "obj"}, {"t": "p", "s": "Түлхүүр үг: IEC 61850, дижитал дэд станц, IED, логик зангилаа, SCL, MMS, GOOSE, Sampled Values, нэгтгэх төхөөрөмж, процессын шина, VLAN, PRP, HSR, PTP, IEC 60870-5-104, SAS, блоклолт.", "h": "<b>Түлхүүр үг:</b> IEC 61850, дижитал дэд станц, IED, логик зангилаа, SCL, MMS, GOOSE, Sampled Values, нэгтгэх төхөөрөмж, процессын шина, VLAN, PRP, HSR, PTP, IEC 60870-5-104, SAS, блоклолт.", "x": "obj"}, {"t": "h", "l": 1, "s": "1. Дэд станцын\nавтоматжуулалтын хөгжил ба IEC 61850", "h": "1. Дэд станцын\nавтоматжуулалтын хөгжил ба IEC 61850"}, {"t": "h", "l": 2, "s": "1.1. Уламжлалт\nсистемээс дижитал дэд станц руу", "h": "1.1. Уламжлалт\nсистемээс дижитал дэд станц руу"}, {"t": "p", "s": "Дэд станцын хоёрдогч систем — хамгаалалт, удирдлага, хэмжилт, бүртгэл, дохиолол — гурван үеийг дамжсан. Эхний үед электромеханик реле, түлхүүр, заагч багажийг удирдлагын самбарт байрлуулж, анхдагч тоноглолтой олон мянган зэс утсаар холбодог байв. Хоёрдугаар үед (1985–2005) микропроцессорт хамгаалалт, RTU нэвтэрч, IED хооронд Modbus, IEC 60870-5-103, DNP3, Profibus зэрэг олон төрлийн, ихэнхдээ үйлдвэрлэгчийн өмчийн протоколоор холбогдох болсон тул нэг дэд станцад хэд хэдэн протокол, хувиргуур зэрэгцэн ажиллаж, өөр үйлдвэрлэгчийн төхөөрөмжийг холбоход өндөр зардал шаардагддаг байв.", "h": "Дэд станцын хоёрдогч систем — хамгаалалт, удирдлага, хэмжилт, бүртгэл, дохиолол — гурван үеийг дамжсан. <b>Эхний үед</b> электромеханик реле, түлхүүр, заагч багажийг удирдлагын самбарт байрлуулж, анхдагч тоноглолтой олон мянган зэс утсаар холбодог байв. <b>Хоёрдугаар үед</b> (1985–2005) микропроцессорт хамгаалалт, RTU нэвтэрч, IED хооронд Modbus, IEC 60870-5-103, DNP3, Profibus зэрэг олон төрлийн, ихэнхдээ үйлдвэрлэгчийн өмчийн протоколоор холбогдох болсон тул нэг дэд станцад хэд хэдэн протокол, хувиргуур зэрэгцэн ажиллаж, өөр үйлдвэрлэгчийн төхөөрөмжийг холбоход өндөр зардал шаардагддаг байв."}, {"t": "p", "s": "Гуравдугаар үе нь IEC 61850-д суурилсан дижитал дэд станц юм. Стандартын анхны хэвлэл 2003–2005 онд гарсан бөгөөд өөр өөр үйлдвэрлэгчийн IED нэг сүлжээнд мэдээлэл солилцож, түүнийгээ зөв тайлбарлан ашиглах харилцан ажиллах чадвар (interoperability)-ыг гол зорилгоо болгосон. IEC 61850 нь зөвхөн протокол биш: функцийн загварчлал, нэрлэлт, системийг тодорхойлох XML хэл (SCL), инженерчлэл, гүйцэтгэлийн шаардлага, тохирлын туршилтыг цогцоор нь тодорхойлдог. Гол зарчмууд нь: өгөгдлийн загварыг (юу дамжуулах) харилцааны зураглалаас (хэрхэн дамжуулах) салгах; өөрийгөө тайлбарлах өгөгдөл («регистр 40017» биш, утгатай нэр); функцийг IED-д чөлөөтэй хуваарилах; хамгаалалтын хурдан мессежийг зэс утасны оронд Ethernet-ээр 3 мс-ийн дотор дамжуулах (GOOSE); MU-ээс агшин утгыг дижитал урсгалаар дамжуулах процессын шина (Sampled Values).", "h": "<b>Гуравдугаар үе</b> нь IEC 61850-д суурилсан <b>дижитал дэд станц</b> юм. Стандартын анхны хэвлэл 2003–2005 онд гарсан бөгөөд өөр өөр үйлдвэрлэгчийн IED нэг сүлжээнд мэдээлэл солилцож, түүнийгээ зөв тайлбарлан ашиглах <b>харилцан ажиллах чадвар</b> (interoperability)-ыг гол зорилгоо болгосон. IEC 61850 нь зөвхөн протокол биш: функцийн загварчлал, нэрлэлт, системийг тодорхойлох XML хэл (SCL), инженерчлэл, гүйцэтгэлийн шаардлага, тохирлын туршилтыг цогцоор нь тодорхойлдог. Гол зарчмууд нь: өгөгдлийн загварыг (юу дамжуулах) харилцааны зураглалаас (хэрхэн дамжуулах) салгах; өөрийгөө тайлбарлах өгөгдөл («регистр 40017» биш, утгатай нэр); функцийг IED-д чөлөөтэй хуваарилах; хамгаалалтын хурдан мессежийг зэс утасны оронд Ethernet-ээр 3 мс-ийн дотор дамжуулах (GOOSE); MU-ээс агшин утгыг дижитал урсгалаар дамжуулах процессын шина (Sampled Values)."}, {"t": "p", "s": "2-р (2009 оноос) ба 2.1 хэвлэл нь хамрах хүрээг «эрчим хүчний байгууламжийн автоматжуулалт» болгон өргөтгөж, усан цахилгаан станц, тархмал үүсгэгч, дэд станц хоорондын ба диспетчерийн төвтэй холбоо, синхрофазорын хэсгүүдийг нэмсэн.", "h": "2-р (2009 оноос) ба 2.1 хэвлэл нь хамрах хүрээг «эрчим хүчний байгууламжийн автоматжуулалт» болгон өргөтгөж, усан цахилгаан станц, тархмал үүсгэгч, дэд станц хоорондын ба диспетчерийн төвтэй холбоо, синхрофазорын хэсгүүдийг нэмсэн."}, {"t": "h", "l": 2, "s": "1.2. IEC 61850 стандартын бүтэц", "h": "1.2. IEC 61850 стандартын бүтэц"}, {"t": "p", "s": "IEC 61850 нь олон хэсгээс бүрдэх цуврал стандарт юм (Хүснэгт 6.1). Инженерийн практикт хамгийн их хэрэглэгддэг нь өгөгдлийн загварын ‑7‑x хэсэг, харилцааны зураглалын ‑8‑1, ‑9‑2 хэсэг, SCL-ийг тодорхойлох ‑6 хэсэг юм.", "h": "IEC 61850 нь олон хэсгээс бүрдэх цуврал стандарт юм (Хүснэгт 6.1). Инженерийн практикт хамгийн их хэрэглэгддэг нь өгөгдлийн загварын ‑7‑x хэсэг, харилцааны зураглалын ‑8‑1, ‑9‑2 хэсэг, SCL-ийг тодорхойлох ‑6 хэсэг юм."}, {"t": "cap", "s": "Хүснэгт 6.1. IEC 61850 цуврал стандартын гол хэсгүүд", "h": "Хүснэгт 6.1. IEC 61850 цуврал стандартын гол хэсгүүд"}, {"t": "tbl", "s": "", "head": ["Хэсэг", "Агуулга"], "rows": [["‑1…‑4", "Танилцуулга, нэр томьёо, ерөнхий шаардлага (орчин, EMC), төслийн удирдлага"], ["‑5", "Функц ба төхөөрөмжийн харилцааны шаардлага (мессежийн төрөл, гүйцэтгэлийн анги)"], ["‑6", "Тохируулгын тодорхойлолтын хэл SCL (XML), файлын төрлүүд"], ["‑7‑1, ‑7‑2", "Загварчлалын зарчим; хийсвэр үйлчилгээний интерфейс ACSI"], ["‑7‑3", "Нийтлэг өгөгдлийн анги (CDC)"], ["‑7‑4", "Логик зангилаа ба өгөгдлийн объектын анги"], ["‑7‑410, ‑7‑420", "Усан цахилгаан станц; тархмал үүсгэгч (DER)"], ["‑8‑1", "ACSI-ийг MMS (ISO 9506) ба ISO/IEC 8802‑3-д буулгах (MMS, GOOSE)"], ["‑9‑2", "Түүвэрлэсэн утгыг (SV) ISO/IEC 8802‑3-д буулгах"], ["‑9‑3", "Нарийн цагийн протоколын (PTP) эрчим хүчний профайл"], ["‑10", "Тохирлын туршилт (conformance testing)"], ["‑80‑1, ‑90‑x", "Техникийн тайлан: IEC 60870-5-101/104-тэй зураглал, дэд станц хоорондын холбоо, диспетчерийн төвтэй холбоо, сүлжээний инженерчлэл, синхрофазор"]]}, {"t": "h", "l": 1, "s": "2. Дижитал дэд станцын\nархитектур", "h": "2. Дижитал дэд станцын\nархитектур"}, {"t": "h", "l": 2, "s": "2.1. Станц, бэй, процессын\nтүвшин", "h": "2.1. Станц, бэй, процессын\nтүвшин"}, {"t": "p", "s": "IEC 61850-5 нь дэд станцын автоматжуулалтын функцийг гурван түвшинд хуваадаг (Зураг 6.1).", "h": "IEC 61850-5 нь дэд станцын автоматжуулалтын функцийг гурван түвшинд хуваадаг (Зураг 6.1)."}, {"t": "p", "s": "Процессын түвшин нь анхдагч тоноглол ба тэдгээртэй шууд холбогдох төхөөрөмжөөс бүрдэнэ. Дижитал дэд станцад энд нэгтгэх төхөөрөмж (MU) гүйдэл, хүчдэлийг түүвэрлэж дижитал урсгал болгоно; аппаратын интерфейс (SAMU, «ухаалаг терминал») таслуур, салгуурын байрлалыг уншиж, команд биелүүлнэ. Тэдгээрийг анхдагч тоноглолын хажууд шкафд байрлуулж, түүнээс дээш бүх холбоог оптик кабелиар хийнэ.", "h": "<b>Процессын түвшин</b> нь анхдагч тоноглол ба тэдгээртэй шууд холбогдох төхөөрөмжөөс бүрдэнэ. Дижитал дэд станцад энд <b>нэгтгэх төхөөрөмж</b> (MU) гүйдэл, хүчдэлийг түүвэрлэж дижитал урсгал болгоно; <b>аппаратын интерфейс</b> (SAMU, «ухаалаг терминал») таслуур, салгуурын байрлалыг уншиж, команд биелүүлнэ. Тэдгээрийг анхдагч тоноглолын хажууд шкафд байрлуулж, түүнээс дээш бүх холбоог оптик кабелиар хийнэ."}, {"t": "p", "s": "Бэйн түвшин нь нэг холболтын хамгаалалт, удирдлага, хэмжилтийн IED (зайн хамгаалалт, ялгаварт хамгаалалт, бэйн удирдлагын төхөөрөмж BCU, тоолуур)-ээс бүрдэж, процессын түвшнээс SV, GOOSE хүлээн авч, станцын түвшинд MMS тайлан илгээнэ.", "h": "<b>Бэйн түвшин</b> нь нэг холболтын хамгаалалт, удирдлага, хэмжилтийн IED (зайн хамгаалалт, ялгаварт хамгаалалт, бэйн удирдлагын төхөөрөмж BCU, тоолуур)-ээс бүрдэж, процессын түвшнээс SV, GOOSE хүлээн авч, станцын түвшинд MMS тайлан илгээнэ."}, {"t": "p", "s": "Станцын түвшин нь HMI, станцын сервер, инженерийн ажлын байр, диспетчерийн төвийн гарц, GNSS цаг, түүхийн сервер, кибер хамгаалалтын хаалтаас бүрдэнэ.", "h": "<b>Станцын түвшин</b> нь HMI, станцын сервер, инженерийн ажлын байр, диспетчерийн төвийн гарц, GNSS цаг, түүхийн сервер, кибер хамгаалалтын хаалтаас бүрдэнэ."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.1. Дижитал дэд станцын гурван түвшинт архитектур", "h": "Зураг 6.1. Дижитал дэд станцын гурван түвшинт архитектур"}, {"t": "p", "s": "Түвшин хоорондын холбоог хоёр сүлжээгээр гүйцэтгэнэ. Станцын шина (station bus) нь бэйн IED-үүдийг хооронд нь болон станцын түвшинтэй холбож, MMS (клиент–серверийн), GOOSE (бэй хоорондын хурдан мессеж), PTP/SNTP цагийн мэдээлэл дамжуулна. Процессын шина (process bus) нь MU, SAMU-г бэйн IED-тэй холбож, SV урсгал, таслах команд, байрлалын GOOSE, PTP дамжуулна. Жижиг дэд станцад хоёр шинаг нэг физик сүлжээнд VLAN-аар тусгаарлан нэгтгэж болох боловч SV-ийн их урсгал, найдвартай ажиллагааны шаардлагаас үүдэн 110 кВ ба түүнээс дээш хүчдэлд ихэвчлэн тусад нь хийдэг.", "h": "Түвшин хоорондын холбоог хоёр сүлжээгээр гүйцэтгэнэ. <b>Станцын шина</b> (station bus) нь бэйн IED-үүдийг хооронд нь болон станцын түвшинтэй холбож, MMS (клиент–серверийн), GOOSE (бэй хоорондын хурдан мессеж), PTP/SNTP цагийн мэдээлэл дамжуулна. <b>Процессын шина</b> (process bus) нь MU, SAMU-г бэйн IED-тэй холбож, SV урсгал, таслах команд, байрлалын GOOSE, PTP дамжуулна. Жижиг дэд станцад хоёр шинаг нэг физик сүлжээнд VLAN-аар тусгаарлан нэгтгэж болох боловч SV-ийн их урсгал, найдвартай ажиллагааны шаардлагаас үүдэн 110 кВ ба түүнээс дээш хүчдэлд ихэвчлэн тусад нь хийдэг."}, {"t": "p", "s": "IEC 61850-5 нь функц хоорондын логик интерфейсийг IF1–IF10 гэж дугаарласан: жишээ нь IF4 — процесс ба бэйн хооронд ГТ, ХТ-ийн агшин утга (SV), IF5 — процесс ба бэйн хооронд удирдлага, IF8 — бэй хоорондын шууд солилцоо (блоклолт), IF10 — алсын удирдлагын төв. Интерфейс бүрийн урсгал, хугацааны шаардлагаар сүлжээний бүтэц, VLAN-ыг сонгоно.", "h": "IEC 61850-5 нь функц хоорондын логик интерфейсийг IF1–IF10 гэж дугаарласан: жишээ нь IF4 — процесс ба бэйн хооронд ГТ, ХТ-ийн агшин утга (SV), IF5 — процесс ба бэйн хооронд удирдлага, IF8 — бэй хоорондын шууд солилцоо (блоклолт), IF10 — алсын удирдлагын төв. Интерфейс бүрийн урсгал, хугацааны шаардлагаар сүлжээний бүтэц, VLAN-ыг сонгоно."}, {"t": "h", "l": 2, "s": "2.2. Ухаалаг электрон төхөөрөмж\n(IED)", "h": "2.2. Ухаалаг электрон төхөөрөмж\n(IED)"}, {"t": "p", "s": "IED (Intelligent Electronic Device) нь нэг буюу хэд хэдэн процессортой, хамгаалалт, удирдлага, хэмжилт, бүртгэл, харилцааны функцийг нэгтгэсэн төхөөрөмж юм (Зураг 6.2). Урд самбарт график дэлгэц, програмчлагдах LED, удирдлагын товчлуур (I, O, L/R), тохируулгын порт; арын самбарт тэжээлийн (=220/110 В, watchdog реле), CPU ба харилцааны (PRP/HSR-ийн хоёр порт, PTP/IRIG-B), аналог оролтын (1/5 А, 100 В), дискрет оролт/гаралтын, процессын шинын оптик модуль байрлана.", "h": "<b>IED</b> (Intelligent Electronic Device) нь нэг буюу хэд хэдэн процессортой, хамгаалалт, удирдлага, хэмжилт, бүртгэл, харилцааны функцийг нэгтгэсэн төхөөрөмж юм (Зураг 6.2). Урд самбарт график дэлгэц, програмчлагдах LED, удирдлагын товчлуур (I, O, L/R), тохируулгын порт; арын самбарт тэжээлийн (=220/110 В, watchdog реле), CPU ба харилцааны (PRP/HSR-ийн хоёр порт, PTP/IRIG-B), аналог оролтын (1/5 А, 100 В), дискрет оролт/гаралтын, процессын шинын оптик модуль байрлана."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.2. Хамгаалалтын IED-ийн урд ба арын самбарын хялбарчилсан зураг", "h": "Зураг 6.2. Хамгаалалтын IED-ийн урд ба арын самбарын хялбарчилсан зураг"}, {"t": "p", "s": "Уламжлалт дэд станцад нэг 110 кВ-ын шугамын бэйд 150–300 зэс хэлхээ байдаг бөгөөд бүгдийг зураг төсөлд тусгаж, угсарч, шалгах шаардлагатай. Дижитал дэд станцад тэдгээрийг 2–6 оптик кабелиар орлуулснаар хяналтын кабель 50–80 %-иар буурч, ГТ-ийн хоёрдогч хэлхээ задрах аюул арилж, цахилгаан соронзон саадын нөлөө (Лекц 11), Монголын нөхцөлд урт кабелийн трассыг хөлдөлт, аянгын индукцээс хамгаалах зардал багасна.", "h": "Уламжлалт дэд станцад нэг 110 кВ-ын шугамын бэйд 150–300 зэс хэлхээ байдаг бөгөөд бүгдийг зураг төсөлд тусгаж, угсарч, шалгах шаардлагатай. Дижитал дэд станцад тэдгээрийг 2–6 оптик кабелиар орлуулснаар хяналтын кабель 50–80 %-иар буурч, ГТ-ийн хоёрдогч хэлхээ задрах аюул арилж, цахилгаан соронзон саадын нөлөө (Лекц 11), Монголын нөхцөлд урт кабелийн трассыг хөлдөлт, аянгын индукцээс хамгаалах зардал багасна."}, {"t": "h", "l": 1, "s": "3. IEC 61850-ийн өгөгдлийн\nзагвар", "h": "3. IEC 61850-ийн өгөгдлийн\nзагвар"}, {"t": "h", "l": 2, "s": "3.1. Объектын шатлал", "h": "3.1. Объектын шатлал"}, {"t": "p", "s": "IEC 61850 нь бодит төхөөрөмжийн функцийг объект хандлагат шатлалаар загварчилна (Зураг 6.3):", "h": "IEC 61850 нь бодит төхөөрөмжийн функцийг объект хандлагат шатлалаар загварчилна (Зураг 6.3):"}, {"t": "p", "s": "Физик төхөөрөмж — сүлжээнд IP, MAC хаягаар холбогдох IED (харилцааны утгаар сервер).", "h": "1. <b>Физик төхөөрөмж</b> — сүлжээнд IP, MAC хаягаар холбогдох IED (харилцааны утгаар <b>сервер</b>)."}, {"t": "p", "s": "Логик төхөөрөмж (LD) — IED доторх функцийн бүлэг: CTRL, PROT, MEAS, DR; LD бүрт заавал LLN0 (өгөгдлийн багц, хяналтын блок) ба LPHD зангилаа байна.", "h": "2. <b>Логик төхөөрөмж</b> (LD) — IED доторх функцийн бүлэг: CTRL, PROT, MEAS, DR; LD бүрт заавал LLN0 (өгөгдлийн багц, хяналтын блок) ба LPHD зангилаа байна."}, {"t": "p", "s": "Логик зангилаа (LN) — стандартаар тодорхойлсон функцийн хамгийн жижиг хэсэг (XCBR — таслуур, PTOC — хэт гүйдлийн хамгаалалт); дөрвөн үсгэн нэр, угтвар, дугаартай: Q1XCBR1.", "h": "3. <b>Логик зангилаа</b> (LN) — стандартаар тодорхойлсон функцийн хамгийн жижиг хэсэг (XCBR — таслуур, PTOC — хэт гүйдлийн хамгаалалт); дөрвөн үсгэн нэр, угтвар, дугаартай: Q1XCBR1."}, {"t": "p", "s": "Өгөгдлийн объект (DO) — Pos (байрлал), OpCnt (ажилласан тоо), A (гүйдэл), Str, Op.", "h": "4. <b>Өгөгдлийн объект</b> (DO) — Pos (байрлал), OpCnt (ажилласан тоо), A (гүйдэл), Str, Op."}, {"t": "p", "s": "Өгөгдлийн атрибут (DA) — stVal (төлөв), q (чанар), t (хугацааны тэмдэг), ctlModel, mag.f.", "h": "5. <b>Өгөгдлийн атрибут</b> (DA) — stVal (төлөв), q (чанар), t (хугацааны тэмдэг), ctlModel, mag.f."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.3. IEC 61850-ийн өгөгдлийн загварын шатлал ба объектын лавлагаа", "h": "Зураг 6.3. IEC 61850-ийн өгөгдлийн загварын шатлал ба объектын лавлагаа"}, {"t": "h", "l": 2, "s": "3.2. Логик зангилааны бүлгүүд", "h": "3.2. Логик зангилааны бүлгүүд"}, {"t": "p", "s": "LN-ийн нэрийн эхний үсэг нь бүлгийг заана (Хүснэгт 6.2). IEC 61850-7-4 Ed.2-т 150 гаруй LN анги тодорхойлогдсон. Стандартад байхгүй функцийг ерөнхий GGIO (оролт/гаралт) зангилаагаар, эсвэл стандартын дүрмийн дагуу шинэ LN-ээр (нэрийн дүрэм, namespace-ийг заан) өргөтгөнө. GGIO-г хэт их хэрэглэх нь харилцан ажиллах чадварыг сулруулна.", "h": "LN-ийн нэрийн эхний үсэг нь бүлгийг заана (Хүснэгт 6.2). IEC 61850-7-4 Ed.2-т 150 гаруй LN анги тодорхойлогдсон. Стандартад байхгүй функцийг ерөнхий GGIO (оролт/гаралт) зангилаагаар, эсвэл стандартын дүрмийн дагуу шинэ LN-ээр (нэрийн дүрэм, namespace-ийг заан) өргөтгөнө. GGIO-г хэт их хэрэглэх нь харилцан ажиллах чадварыг сулруулна."}, {"t": "cap", "s": "Хүснэгт 6.2. Логик зангилааны бүлгүүд ба жишээ", "h": "Хүснэгт 6.2. Логик зангилааны бүлгүүд ба жишээ"}, {"t": "tbl", "s": "", "head": ["Үсэг", "Бүлэг", "Жишээ LN (ANSI код)"], "rows": [["L", "Системийн LN", "LLN0, LPHD, LGOS (GOOSE захиалгын хяналт), LTMS (цаг)"], ["P", "Хамгаалалт", "PDIS (21), PTOC (51), PIOC (50), PDIF (87), PTOV (59), PTUF (81U), PTRC (таслах нөхцөл)"], ["R", "Хамгаалалттай холбоотой", "RREC (79, АДЗ), RBRF (50BF, таслуурын татгалзал), RDRE (гэмтлийн бүртгэгч), RSYN (25)"], ["C", "Удирдлага", "CSWI (аппаратын удирдлага), CILO (блоклолт), CPOW (point-on-wave)"], ["A", "Автомат тохируулга", "ATCC (OLTC-ийн хүчдэлийн тохируулга), ANCR (нейтралын реактор)"], ["M", "Хэмжилт, тоолуур", "MMXU (3 фазын хэмжилт), MMTR (тоолуур), MSQI (тэгш хэмт бүрдүүлэгч), MHAI (гармоник)"], ["X", "Коммутацын аппарат", "XCBR (таслуур), XSWI (салгуур, газардуулагч)"], ["T", "Хэмжүүрийн трансформатор", "TCTR (ГТ), TVTR (ХТ)"], ["Y", "Хүчний трансформатор", "YPTR (трансформатор), YLTC (OLTC), YEFN (нейтраль)"], ["S", "Хяналт, оношлогоо", "SIMG (SF6 нягт), SIML (тосны хяналт), SCBR (таслуурын хяналт), SARC (нум)"], ["Z", "Бусад тоноглол", "ZBAT (батарей), ZCAP (конденсатор), ZREA (реактор), ZLIN (шугам)"], ["G, I, K, Q", "Ерөнхий, архив, механик, чанар", "GGIO, GAPC; IHMI, IARC; KFAN; QVVR (хүчдэлийн уналт)"]]}, {"t": "p", "s": "Жишээ нь шугамын хамгаалалтад MU-ийн TCTR1–4, TVTR1–4 гүйдэл, хүчдэлийг нийтэлж, IED-ийн PDIS1–4, PTOC1, RREC1, RBRF1 ажиллаж, PTRC1.Tr нь GOOSE-ээр SAMU-ийн XCBR1-д хүрч таслуурыг таслана — зэс утсан хэлхээний логик LN хоорондын өгөгдлийн холбоос болж хувирна.", "h": "Жишээ нь шугамын хамгаалалтад MU-ийн TCTR1–4, TVTR1–4 гүйдэл, хүчдэлийг нийтэлж, IED-ийн PDIS1–4, PTOC1, RREC1, RBRF1 ажиллаж, PTRC1.Tr нь GOOSE-ээр SAMU-ийн XCBR1-д хүрч таслуурыг таслана — зэс утсан хэлхээний логик LN хоорондын өгөгдлийн холбоос болж хувирна."}, {"t": "h", "l": 2, "s": "3.3. Нийтлэг\nөгөгдлийн анги ба функциональ хязгаарлалт", "h": "3.3. Нийтлэг\nөгөгдлийн анги ба функциональ хязгаарлалт"}, {"t": "p", "s": "DO бүр нь нийтлэг өгөгдлийн анги (Common Data Class, CDC)-ийн нэг төрөл байна. CDC нь DO-д ямар DA байхыг тодорхойлно: жишээ нь DPC (давхар цэгийн удирдлагатай төлөв) нь stVal, q, t, ctlModel, Oper, SBOw зэрэг атрибуттай. DA бүр функциональ хязгаарлалт (Functional Constraint, FC)-тай бөгөөд энэ нь тухайн атрибутыг юунд ашиглах, унших/бичих эрхийг заана (Хүснэгт 6.3).", "h": "DO бүр нь <b>нийтлэг өгөгдлийн анги</b> (Common Data Class, CDC)-ийн нэг төрөл байна. CDC нь DO-д ямар DA байхыг тодорхойлно: жишээ нь DPC (давхар цэгийн удирдлагатай төлөв) нь stVal, q, t, ctlModel, Oper, SBOw зэрэг атрибуттай. DA бүр <b>функциональ хязгаарлалт</b> (Functional Constraint, FC)-тай бөгөөд энэ нь тухайн атрибутыг юунд ашиглах, унших/бичих эрхийг заана (Хүснэгт 6.3)."}, {"t": "cap", "s": "Хүснэгт 6.3. Түгээмэл CDC ба функциональ хязгаарлалт", "h": "Хүснэгт 6.3. Түгээмэл CDC ба функциональ хязгаарлалт"}, {"t": "tbl", "s": "", "head": ["CDC", "Утга", "Жишээ DO", "FC", "Утга"], "rows": [["SPS", "Нэг цэгийн төлөв", "Str, Op (зарим LN-д ACD)", "ST", "Төлөвийн мэдээлэл"], ["DPS", "Давхар цэгийн төлөв", "Pos (удирдлагагүй)", "MX", "Хэмжсэн утга"], ["INS, ENS", "Бүхэл/тоочсон төлөв", "OpCnt, Beh, Health", "CO", "Удирдлага (команд)"], ["ACD, ACT", "Хамгаалалтын идэвхжил (чиглэлтэй)", "Str, Op", "SP, SG, SE", "Тохируулгын параметр, бүлэг"], ["MV, CMV", "Хэмжсэн утга (комплекс)", "TotW, Hz; PhV.phsA", "CF", "Тохируулга (configuration)"], ["WYE, DEL", "Фаз–газар, фаз хоорондын 3 фазын утга", "PhV, A; PPV", "DC, EX", "Тайлбар, өргөтгөл"], ["SPC, DPC, INC", "Удирдлагатай төлөв", "Pos, BlkOpn, TapChg", "SV", "Орлуулах (substitution)"], ["ASG, ING", "Тохируулгын аналог/бүхэл утга", "StrVal, OpDlTmms", "BL, OR", "Блоклох; командын эх үүсвэр"]]}, {"t": "p", "s": "Давхар цэгийн байрлал (DPS, DPC) хоёр битээр кодлогдоно: 00 — завсрын, 01 — тасархай, 10 — залгаатай, 11 — буруу; хоёр туслах контакт (52a, 52b) нь утас тасрах, контакт гацахыг илрүүлнэ.", "h": "Давхар цэгийн байрлал (DPS, DPC) хоёр битээр кодлогдоно: 00 — завсрын, 01 — тасархай, 10 — залгаатай, 11 — буруу; хоёр туслах контакт (52a, 52b) нь утас тасрах, контакт гацахыг илрүүлнэ."}, {"t": "p", "s": "Чанарын атрибут q нь утгын найдвартай байдлыг (validity: good, invalid, questionable; гэмтлийн шалтгаан; source; test; operatorBlocked) илэрхийлнэ. Захиалагч q-г заавал шалгаж, invalid эсвэл test тэмдэгтэй утгыг хамгаалалт, блоклолтод ашиглахгүй. Хугацааны тэмдэг t нь 1970.01.01-нээс хойших секунд, секундын хэсэг, цагийн чанарын байтаас бүрдэнэ.", "h": "<b>Чанарын атрибут q</b> нь утгын найдвартай байдлыг (validity: good, invalid, questionable; гэмтлийн шалтгаан; source; test; operatorBlocked) илэрхийлнэ. Захиалагч q-г заавал шалгаж, invalid эсвэл test тэмдэгтэй утгыг хамгаалалт, блоклолтод ашиглахгүй. <b>Хугацааны тэмдэг t</b> нь 1970.01.01-нээс хойших секунд, секундын хэсэг, цагийн чанарын байтаас бүрдэнэ."}, {"t": "h", "l": 2, "s": "3.4. Нэрлэлт ба объектын\nлавлагаа", "h": "3.4. Нэрлэлт ба объектын\nлавлагаа"}, {"t": "p", "s": "Объектын лавлагаа (object reference) нь шатлалын нэрсийг тусгаарлагч тэмдгээр холбосон мөр юм:", "h": "Объектын лавлагаа (object reference) нь шатлалын нэрсийг тусгаарлагч тэмдгээр холбосон мөр юм:"}, {"t": "p", "s": "LDName/[Prefix]LNClass[Inst].DO[.SubDO].DA[.SubDA]", "h": "LDName/[Prefix]LNClass[Inst].DO[.SubDO].DA[.SubDA]"}, {"t": "p", "s": "Жишээ нь E1Q1_BCUCTRL/Q0XCBR1.Pos.stVal нь «E1Q1_BCU нэртэй IED-ийн CTRL логик төхөөрөмж дэх Q0 угтвартай 1-р таслуурын байрлалын төлөвийн утга» юм. Логик төхөөрөмжийн нэрийг ихэвчлэн IED-ийн нэр ба LD-ийн нэрийг залгаж үүсгэнэ (Ed.2-т LD нэрийн урт 64 тэмдэгт хүртэл). MMS-д буулгахад цэгийн оронд «доллар» тэмдэг хэрэглэж, LN-ийн нэрийн дараа FC-г оруулна (Q0XCBR1, ST, Pos, stVal дараалал).", "h": "Жишээ нь <b>E1Q1_BCUCTRL/Q0XCBR1.Pos.stVal</b> нь «E1Q1_BCU нэртэй IED-ийн CTRL логик төхөөрөмж дэх Q0 угтвартай 1-р таслуурын байрлалын төлөвийн утга» юм. Логик төхөөрөмжийн нэрийг ихэвчлэн IED-ийн нэр ба LD-ийн нэрийг залгаж үүсгэнэ (Ed.2-т LD нэрийн урт 64 тэмдэгт хүртэл). MMS-д буулгахад цэгийн оронд «доллар» тэмдэг хэрэглэж, LN-ийн нэрийн дараа FC-г оруулна (Q0XCBR1, ST, Pos, stVal дараалал)."}, {"t": "p", "s": "Нэрлэлтийг IEC 81346-ийн тэмдэглэгээтэй уялдуулна (E1 — 110 кВ, Q1 — бэй, Q0 — таслуур, Q9 — шугамын салгуур); Монголын диспетчерийн тэмдэглэгээг SCL-ийн desc атрибутад хадгална.", "h": "Нэрлэлтийг IEC 81346-ийн тэмдэглэгээтэй уялдуулна (E1 — 110 кВ, Q1 — бэй, Q0 — таслуур, Q9 — шугамын салгуур); Монголын диспетчерийн тэмдэглэгээг SCL-ийн desc атрибутад хадгална."}, {"t": "h", "l": 2, "s": "3.5. Удирдлагын загвар ба горим", "h": "3.5. Удирдлагын загвар ба горим"}, {"t": "p", "s": "Коммутацын аппаратын удирдлагын аюулгүй байдлыг удирдлагын загвар (ctlModel) хангана: status-only, direct-with-normal-security, sbo-with-normal-security, direct-with-enhanced-security, sbo-with-enhanced-security. Таслуур, салгуурт ихэвчлэн сүүлийнхийг хэрэглэнэ: сонгохдоо утгыг хамт илгээж (SBOw), гүйцэтгэсний дараа байрлал өөрчлөгдсөнийг шалгаад CommandTermination буцаана; команд нь orCat (эх үүсвэр), interlockCheck, synchroCheck тугтай.", "h": "Коммутацын аппаратын удирдлагын аюулгүй байдлыг <b>удирдлагын загвар</b> (ctlModel) хангана: status-only, direct-with-normal-security, sbo-with-normal-security, direct-with-enhanced-security, sbo-with-enhanced-security. Таслуур, салгуурт ихэвчлэн сүүлийнхийг хэрэглэнэ: сонгохдоо утгыг хамт илгээж (SBOw), гүйцэтгэсний дараа байрлал өөрчлөгдсөнийг шалгаад CommandTermination буцаана; команд нь orCat (эх үүсвэр), interlockCheck, synchroCheck тугтай."}, {"t": "p", "s": "LN бүр Mod (горим) ба Beh (зан төлөв) объекттой: on, on-blocked, test, test/blocked, off. Beh нь тухайн LN болон түүний харьяалагдах LD-ийн горимоос тодорхойлогдоно. Энэ механизмыг туршилт, засварт ашиглах талаар 10-р бүлэгт үзнэ.", "h": "LN бүр <b>Mod</b> (горим) ба <b>Beh</b> (зан төлөв) объекттой: on, on-blocked, test, test/blocked, off. Beh нь тухайн LN болон түүний харьяалагдах LD-ийн горимоос тодорхойлогдоно. Энэ механизмыг туршилт, засварт ашиглах талаар 10-р бүлэгт үзнэ."}, {"t": "h", "l": 1, "s": "4. SCL ба инженерчлэлийн\nдараалал", "h": "4. SCL ба инженерчлэлийн\nдараалал"}, {"t": "h", "l": 2, "s": "4.1. SCL файлын төрлүүд", "h": "4.1. SCL файлын төрлүүд"}, {"t": "p", "s": "SCL (Substation Configuration Language, IEC 61850-6) нь XML-д суурилсан хэл бөгөөд дэд станцын анхдагч схем (Substation хэсэг), харилцааны сүлжээ (Communication), IED-ийн чадвар ба тохируулга (IED), өгөгдлийн төрлийн загвар (DataTypeTemplates)-ыг нэг форматаар тодорхойлно. Зорилгоос хамааран файлын төрөл ялгаатай (Хүснэгт 6.4).", "h": "<b>SCL</b> (Substation Configuration Language, IEC 61850-6) нь XML-д суурилсан хэл бөгөөд дэд станцын анхдагч схем (Substation хэсэг), харилцааны сүлжээ (Communication), IED-ийн чадвар ба тохируулга (IED), өгөгдлийн төрлийн загвар (DataTypeTemplates)-ыг нэг форматаар тодорхойлно. Зорилгоос хамааран файлын төрөл ялгаатай (Хүснэгт 6.4)."}, {"t": "cap", "s": "Хүснэгт 6.4. SCL файлын төрлүүд", "h": "Хүснэгт 6.4. SCL файлын төрлүүд"}, {"t": "tbl", "s": "", "head": ["Файл", "Бүтэн нэр", "Хэн үүсгэх", "Агуулга"], "rows": [["SSD", "System Specification Description", "Захиалагч / зураг төсөлч", "Нэг шугамын схем, бэй, аппарат, шаардлагатай LN-ийн хуваарилалт"], ["ICD", "IED Capability Description", "IED-ийн үйлдвэрлэгч", "IED-ийн ерөнхий чадвар: LD, LN, DO, үйлчилгээ (хоосон тохируулга)"], ["IID", "Instantiated IED Description", "IED-ийн хэрэгсэл (ICT)", "Төслийн тодорхой IED (нэр, хаяг, өгөгдлийн багц)"], ["SCD", "Substation Configuration Description", "Системийн хэрэгсэл (SCT)", "Бүх IED, сүлжээ, GOOSE/SV холбоос, схем — дэд станцын бүрэн тодорхойлолт"], ["CID", "Configured IED Description", "ICT", "SCD-ээс нэг IED-д ачаалах тохируулга"], ["SED", "System Exchange Description", "SCT", "Өөр төслийн (дэд станц, диспетчерийн төв) хоорондын интерфейс"]]}, {"t": "h", "l": 2, "s": "4.2. Инженерчлэлийн дараалал", "h": "4.2. Инженерчлэлийн дараалал"}, {"t": "p", "s": "Инженерчлэлийг ихэвчлэн «дээрээс доош» (top-down) аргаар гүйцэтгэнэ (Зураг 6.4). Эхлээд нэг шугамын схем, функцийн шаардлагыг SSD файлд тодорхойлно. Үйлдвэрлэгч бүр өөрийн IED-ийн ICD файлыг өгнө. Системийн тохируулгын хэрэгсэл (SCT) нь ICD-үүдийг импортлож, IED бүрт нэр, IP хаяг, VLAN, MAC хаяг олгож, LN-ийг схемийн аппараттай холбож, өгөгдлийн багц (DataSet), тайлангийн хяналтын блок (RCB), GOOSE ба SV-ийн хяналтын блок (GoCB, MSVCB) үүсгэж, нийтлэгч–захиалагчийн холбоосыг (ExtRef) тодорхойлно. Үр дүн нь SCD файл юм. Үүнийг IED-ийн хэрэгсэл (ICT) импортлон, IED бүрийн CID файлыг үүсгэж ачаална. Мөн SCD-ээс HMI-ийн мэдээллийн сан, гарцын хүснэгт, туршилтын хэрэгслийн тохируулгыг автоматаар үүсгэх боломжтой.", "h": "Инженерчлэлийг ихэвчлэн «дээрээс доош» (top-down) аргаар гүйцэтгэнэ (Зураг 6.4). Эхлээд нэг шугамын схем, функцийн шаардлагыг SSD файлд тодорхойлно. Үйлдвэрлэгч бүр өөрийн IED-ийн ICD файлыг өгнө. Системийн тохируулгын хэрэгсэл (SCT) нь ICD-үүдийг импортлож, IED бүрт нэр, IP хаяг, VLAN, MAC хаяг олгож, LN-ийг схемийн аппараттай холбож, өгөгдлийн багц (DataSet), тайлангийн хяналтын блок (RCB), GOOSE ба SV-ийн хяналтын блок (GoCB, MSVCB) үүсгэж, нийтлэгч–захиалагчийн холбоосыг (ExtRef) тодорхойлно. Үр дүн нь SCD файл юм. Үүнийг IED-ийн хэрэгсэл (ICT) импортлон, IED бүрийн CID файлыг үүсгэж ачаална. Мөн SCD-ээс HMI-ийн мэдээллийн сан, гарцын хүснэгт, туршилтын хэрэгслийн тохируулгыг автоматаар үүсгэх боломжтой."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.4. SCL файлд суурилсан инженерчлэлийн дараалал", "h": "Зураг 6.4. SCL файлд суурилсан инженерчлэлийн дараалал"}, {"t": "p", "s": "Гол давуу тал нь мэдээллийн нэг эх сурвалж юм: сигналын жагсаалт, HMI-ийн мэдээллийн сан, гарцын хүснэгтийг (110 кВ-ын дэд станцад 3000–6000 сигнал) гараар бус SCD-ээс үүсгэнэ. Практикт өөр үйлдвэрлэгчийн хэрэгслүүд SCL-ийн өөр хувилбарыг дэмжих, зарим IED тогтмол өгөгдлийн багцтай байх хүндрэл гардаг тул тендерт PICS, PIXIT, TICS баримт, тохирлын гэрчилгээ шаардаж, SCD-г хувилбартайгаар хадгална.", "h": "Гол давуу тал нь <b>мэдээллийн нэг эх сурвалж</b> юм: сигналын жагсаалт, HMI-ийн мэдээллийн сан, гарцын хүснэгтийг (110 кВ-ын дэд станцад 3000–6000 сигнал) гараар бус SCD-ээс үүсгэнэ. Практикт өөр үйлдвэрлэгчийн хэрэгслүүд SCL-ийн өөр хувилбарыг дэмжих, зарим IED тогтмол өгөгдлийн багцтай байх хүндрэл гардаг тул тендерт PICS, PIXIT, TICS баримт, тохирлын гэрчилгээ шаардаж, SCD-г хувилбартайгаар хадгална."}, {"t": "h", "l": 1, "s": "5. ACSI ба харилцааны зураглал", "h": "5. ACSI ба харилцааны зураглал"}, {"t": "h", "l": 2, "s": "5.1. Хийсвэр үйлчилгээ ба\nMMS клиент–сервер", "h": "5.1. Хийсвэр үйлчилгээ ба\nMMS клиент–сервер"}, {"t": "p", "s": "IEC 61850-7-2 нь ACSI (Abstract Communication Service Interface) буюу протоколоос хамааралгүй хийсвэр үйлчилгээг тодорхойлно. Үүнд холболт (Associate), бүтцийг асуух, утга унших/бичих (GetDataValues, SetDataValues), тайлан, бүртгэл, удирдлага (Select, Operate, Cancel), файл дамжуулах (COMTRADE), GOOSE, SV орно. Эдгээрийг бодит протоколд буулгах дүрмийг зураглал (mapping) гэнэ: клиент–серверийн үйлчилгээг MMS (ISO 9506) → TCP/IP (порт 102)-д, GOOSE-ийг Ethernet-д шууд (IEC 61850-8-1), SV-ийг Ethernet-д шууд (IEC 61850-9-2) буулгана.", "h": "IEC 61850-7-2 нь <b>ACSI</b> (Abstract Communication Service Interface) буюу протоколоос хамааралгүй хийсвэр үйлчилгээг тодорхойлно. Үүнд холболт (Associate), бүтцийг асуух, утга унших/бичих (GetDataValues, SetDataValues), тайлан, бүртгэл, удирдлага (Select, Operate, Cancel), файл дамжуулах (COMTRADE), GOOSE, SV орно. Эдгээрийг бодит протоколд буулгах дүрмийг <b>зураглал</b> (mapping) гэнэ: клиент–серверийн үйлчилгээг MMS (ISO 9506) → TCP/IP (порт 102)-д, GOOSE-ийг Ethernet-д шууд (IEC 61850-8-1), SV-ийг Ethernet-д шууд (IEC 61850-9-2) буулгана."}, {"t": "p", "s": "MMS тайлан нь станцын түвшинд мэдээлэл дамжуулах гол арга юм. Сервер дахь тайлангийн хяналтын блок (Report Control Block) нь өгөгдлийн багцыг хянаж, өдөөгч нөхцөл (trigger options) биелэхэд клиентэд тайлан илгээнэ: dchg — утга өөрчлөгдөх, qchg — чанар өөрчлөгдөх, dupd — утга шинэчлэгдэх, integrity — тогтмол хугацаанд бүх утга, GI — клиентийн хүсэлтээр ерөнхий асуулга. Буферт тайлан (BRCB) нь холбоо тасарсан үед үйл явдлыг буферт хадгалж, холбоо сэргэхэд дарааллаар нь илгээдэг тул дохиолол, таслуурын байрлалд хэрэглэнэ; буфергүй тайлан (URCB) нь хэмжилтэд тохиромжтой. Хэмжилтийн тайланд «мэдрэмжгүй бүс» (deadband, db атрибут) тогтоож, утга тодорхой хэмжээгээр өөрчлөгдөх үед л илгээснээр сүлжээний ачааллыг бууруулна. TCP-д суурилсан MMS-ийн хоцролт хэдэн арван–зуун мс тул хамгаалалтын хурдан функцэд тохиромжгүй.", "h": "<b>MMS тайлан</b> нь станцын түвшинд мэдээлэл дамжуулах гол арга юм. Сервер дахь тайлангийн хяналтын блок (Report Control Block) нь өгөгдлийн багцыг хянаж, өдөөгч нөхцөл (trigger options) биелэхэд клиентэд тайлан илгээнэ: dchg — утга өөрчлөгдөх, qchg — чанар өөрчлөгдөх, dupd — утга шинэчлэгдэх, integrity — тогтмол хугацаанд бүх утга, GI — клиентийн хүсэлтээр ерөнхий асуулга. <b>Буферт тайлан</b> (BRCB) нь холбоо тасарсан үед үйл явдлыг буферт хадгалж, холбоо сэргэхэд дарааллаар нь илгээдэг тул дохиолол, таслуурын байрлалд хэрэглэнэ; <b>буфергүй тайлан</b> (URCB) нь хэмжилтэд тохиромжтой. Хэмжилтийн тайланд «мэдрэмжгүй бүс» (deadband, db атрибут) тогтоож, утга тодорхой хэмжээгээр өөрчлөгдөх үед л илгээснээр сүлжээний ачааллыг бууруулна. TCP-д суурилсан MMS-ийн хоцролт хэдэн арван–зуун мс тул хамгаалалтын хурдан функцэд тохиромжгүй."}, {"t": "h", "l": 2, "s": "5.2. Мессежийн төрөл ба\nгүйцэтгэлийн анги", "h": "5.2. Мессежийн төрөл ба\nгүйцэтгэлийн анги"}, {"t": "p", "s": "IEC 61850-5 нь мессежийг хугацааны шаардлагаар ангилж, дамжуулах хугацаа (transfer time)-г тодорхойлдог. Дамжуулах хугацаа нь илгээгч функц өгөгдлийг харилцааны стект өгснөөс хүлээн авагч функц түүнийг авах хүртэлх нийт хугацаа юм:", "h": "IEC 61850-5 нь мессежийг хугацааны шаардлагаар ангилж, <b>дамжуулах хугацаа</b> (transfer time)-г тодорхойлдог. Дамжуулах хугацаа нь илгээгч функц өгөгдлийг харилцааны стект өгснөөс хүлээн авагч функц түүнийг авах хүртэлх нийт хугацаа юм:"}, {"t": "eq", "s": "t=t a+t b+t c (6.1)", "h": "t=t<sub>a</sub>+t<sub>b</sub>+t<sub>c</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t</mi><mo>=</mo><msub><mi>t</mi><mi>a</mi></msub><mo>+</mo><msub><mi>t</mi><mi>b</mi></msub><mo>+</mo><msub><mi>t</mi><mi>c</mi></msub></mrow></semantics></math>", "n": "6.1"}, {"t": "p", "s": "энд t a — илгээгч IED-ийн харилцааны боловсруулалтын хугацаа; t b — сүлжээгээр дамжих хугацаа (кабель, свич); t c — хүлээн авагч IED-ийн боловсруулалтын хугацаа. Функцийн өөрийн хугацаа (хамгаалалтын алгоритм, гаралтын реле) энд орохгүй. Мессежийн төрөл ба гүйцэтгэлийн ангийг Хүснэгт 6.5-д үзүүлэв. Дамжуулах хугацааны анги TT0–TT6 гэж тэмдэглэгдэнэ: TT0 >1000 мс, TT1 1000 мс, TT2 500 мс, TT3 100 мс, TT4 20 мс, TT5 10 мс, TT6 3 мс.", "h": "энд t<sub>a</sub> — илгээгч IED-ийн харилцааны боловсруулалтын хугацаа; t<sub>b</sub> — сүлжээгээр дамжих хугацаа (кабель, свич); t<sub>c</sub> — хүлээн авагч IED-ийн боловсруулалтын хугацаа. Функцийн өөрийн хугацаа (хамгаалалтын алгоритм, гаралтын реле) энд орохгүй. Мессежийн төрөл ба гүйцэтгэлийн ангийг Хүснэгт 6.5-д үзүүлэв. Дамжуулах хугацааны анги TT0–TT6 гэж тэмдэглэгдэнэ: TT0 &gt;1000 мс, TT1 1000 мс, TT2 500 мс, TT3 100 мс, TT4 20 мс, TT5 10 мс, TT6 3 мс."}, {"t": "cap", "s": "Хүснэгт 6.5. Мессежийн төрөл ба шаардлагатай дамжуулах хугацаа (IEC 61850-5)", "h": "Хүснэгт 6.5. Мессежийн төрөл ба шаардлагатай дамжуулах хугацаа (IEC 61850-5)"}, {"t": "tbl", "s": "", "head": ["Төрөл", "Мессеж", "Жишээ", "Анги", "Хугацаа", "Зураглал"], "rows": [["1A", "Хурдан: таслах", "Хамгаалалтын таслах, блоклох дохио", "TT6", "≤ 3 мс (P2/P3), ≤ 10 мс (P1)", "GOOSE"], ["1B", "Хурдан: бусад", "Блоклолт, байрлал, АДЗ эхлүүлэх", "TT4–TT5", "≤ 10–20 мс", "GOOSE"], ["2", "Дунд хурдтай", "Хэмжилт, төлөв (хугацааны тэмдэгтэй)", "TT3", "≤ 100 мс", "MMS тайлан"], ["3", "Удаан", "Тохируулга, дохиолол, бүртгэл", "TT2", "≤ 500 мс", "MMS"], ["4", "Түүхий өгөгдөл", "ГТ, ХТ-ийн түүвэрлэсэн утга", "TT6", "≤ 3 мс", "SV"], ["5", "Файл дамжуулах", "Осциллограмм, тохируулгын файл", "TT0", "≥ 1000 мс", "MMS файл"], ["6", "Цаг синхрончлол", "Цагийн мессеж", "—", "Нарийвчлалын анги T0–T5", "PTP, SNTP"], ["7", "Хандалтын хяналттай команд", "Операторын команд", "TT2", "≤ 500 мс", "MMS удирдлага"]]}, {"t": "h", "l": 2, "s": "5.3. GOOSE мессеж", "h": "5.3. GOOSE мессеж"}, {"t": "p", "s": "GOOSE (Generic Object Oriented Substation Event) нь нэг нийтлэгч (publisher) IED-ээс олон захиалагч (subscriber) руу өгөгдлийн багцыг Ethernet-ийн давхаргад шууд (IP, TCP ашиглахгүй) олон хаягт (multicast) хэлбэрээр дамжуулах үйлчилгээ юм. GOOSE кадр нь EtherType 0x88B8, хүлээн авагчийн MAC хаяг 01‑0C‑CD‑01‑xx‑xx муж, APPID 0x0000–0x3FFF, IEEE 802.1Q VLAN шошго (ихэвчлэн приоритет 4–6)-той. Кадрт gocbRef (хяналтын блокийн лавлагаа), datSet, goID, хүлээн авах хугацаа (timeAllowedToLive), хугацааны тэмдэг, stNum, sqNum, simulation, confRev, ndsCom, өгөгдлийн утгууд багтана.", "h": "<b>GOOSE</b> (Generic Object Oriented Substation Event) нь нэг нийтлэгч (publisher) IED-ээс олон захиалагч (subscriber) руу өгөгдлийн багцыг Ethernet-ийн давхаргад шууд (IP, TCP ашиглахгүй) олон хаягт (multicast) хэлбэрээр дамжуулах үйлчилгээ юм. GOOSE кадр нь EtherType 0x88B8, хүлээн авагчийн MAC хаяг 01‑0C‑CD‑01‑xx‑xx муж, APPID 0x0000–0x3FFF, IEEE 802.1Q VLAN шошго (ихэвчлэн приоритет 4–6)-той. Кадрт gocbRef (хяналтын блокийн лавлагаа), datSet, goID, хүлээн авах хугацаа (timeAllowedToLive), хугацааны тэмдэг, stNum, sqNum, simulation, confRev, ndsCom, өгөгдлийн утгууд багтана."}, {"t": "p", "s": "TCP-ийн баталгаажуулалт (хүлээн авсныг мэдэгдэх) байхгүй тул GOOSE нь давтан илгээх механизмаар найдвартай байдлыг хангана. Өгөгдлийн багцын аль нэг утга өөрчлөгдөхөд IED тэр даруй мессеж илгээж, дараа нь богино завсартайгаар хэд хэдэн удаа давтаад, завсрыг аажмаар уртасгаж тогтвортой завсар T 0-д хүрнэ (Зураг 6.5):", "h": "TCP-ийн баталгаажуулалт (хүлээн авсныг мэдэгдэх) байхгүй тул GOOSE нь <b>давтан илгээх</b> механизмаар найдвартай байдлыг хангана. Өгөгдлийн багцын аль нэг утга өөрчлөгдөхөд IED тэр даруй мессеж илгээж, дараа нь богино завсартайгаар хэд хэдэн удаа давтаад, завсрыг аажмаар уртасгаж тогтвортой завсар T<sub>0</sub>-д хүрнэ (Зураг 6.5):"}, {"t": "eq", "s": "T i=min (T 1⋅2^ i−1, T 0), i=1,2,3,… (6.2)", "h": "T<sub>i</sub>=min (T<sub>1</sub>⋅2<sup> i−1</sup>, T<sub>0</sub>), i=1,2,3,…", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T</mi><mi>i</mi></msub><mo>=</mo><mo>min</mo><mspace width=\"-0.167em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>T</mi><mn>1</mn></msub><mo>⋅</mo><msup><mn>2</mn><mrow><mspace width=\"0.167em\"></mspace><mi>i</mi><mo>−</mo><mn>1</mn></mrow></msup><mo>,</mo><mspace width=\"0.278em\"></mspace><msub><mi>T</mi><mn>0</mn></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>i</mi><mo>=</mo><mn>1</mn><mo>,</mo><mn>2</mn><mo>,</mo><mn>3</mn><mo>,</mo><mi>…</mi></mrow></semantics></math>", "n": "6.2"}, {"t": "p", "s": "энд T 1 — үйл явдлын дараах анхны завсар (ихэвчлэн 1–4 мс); T 0 — тогтвортой үеийн «зүрхний цохилт» (heartbeat) завсар (ихэвчлэн 1–5 с, Ed.2-т тохируулна). Давтах завсрын хэлбэрийг стандарт тогтоогоогүй, үйлдвэрлэгч тодорхойлдог бөгөөд (6.2) нь түгээмэл хоёр дахин өсгөх хувилбар юм.", "h": "энд T<sub>1</sub> — үйл явдлын дараах анхны завсар (ихэвчлэн 1–4 мс); T<sub>0</sub> — тогтвортой үеийн «зүрхний цохилт» (heartbeat) завсар (ихэвчлэн 1–5 с, Ed.2-т тохируулна). Давтах завсрын хэлбэрийг стандарт тогтоогоогүй, үйлдвэрлэгч тодорхойлдог бөгөөд (6.2) нь түгээмэл хоёр дахин өсгөх хувилбар юм."}, {"t": "p", "s": "Төлвийн дугаар stNum нь өгөгдлийн утга өөрчлөгдөх бүрт нэгээр нэмэгдэнэ; дарааллын дугаар sqNum нь ижил төлөвт давтан илгээх бүрт нэмэгдэж, шинэ төлөвт 0 болно. Захиалагч stNum өөрчлөгдсөнийг харж шинэ үйл явдлыг, sqNum-ын тасралтаар мессеж алдагдсаныг илрүүлнэ. Кадр бүр хүлээн авах хугацаа (TAL)-тай:", "h": "<b>Төлвийн дугаар stNum</b> нь өгөгдлийн утга өөрчлөгдөх бүрт нэгээр нэмэгдэнэ; <b>дарааллын дугаар sqNum</b> нь ижил төлөвт давтан илгээх бүрт нэмэгдэж, шинэ төлөвт 0 болно. Захиалагч stNum өөрчлөгдсөнийг харж шинэ үйл явдлыг, sqNum-ын тасралтаар мессеж алдагдсаныг илрүүлнэ. Кадр бүр <b>хүлээн авах хугацаа</b> (TAL)-тай:"}, {"t": "eq", "s": "TAL=k⋅T дараах, k≈2 (6.3)", "h": "TAL=k⋅T<sub>дараах</sub>, k≈2", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi><mi>A</mi><mi>L</mi><mo>=</mo><mi>k</mi><mo>⋅</mo><msub><mi>T</mi><mrow><mi>д</mi><mi>а</mi><mi>р</mi><mi>а</mi><mi>а</mi><mi>х</mi></mrow></msub><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>k</mi><mo>≈</mo><mn>2</mn></mrow></semantics></math>", "n": "6.3"}, {"t": "p", "s": "энд T дараах — дараагийн мессеж хүртэлх хүлээгдэж буй завсар. Захиалагч TAL хугацаанд шинэ мессеж аваагүй бол холбоо тасарсан гэж үзэж, өгөгдлийн чанарыг invalid болгон, LGOS зангилаагаар дохиолол өгнө. Ингэснээр «чимээгүй» холбооны гэмтэл хамгийн ихдээ 2T 0 хугацаанд илэрнэ — энэ нь уламжлалт зэс утсан хэлхээнд байдаггүй, тасралтгүй өөрийгөө хянах давуу тал юм.", "h": "энд T<sub>дараах</sub> — дараагийн мессеж хүртэлх хүлээгдэж буй завсар. Захиалагч TAL хугацаанд шинэ мессеж аваагүй бол холбоо тасарсан гэж үзэж, өгөгдлийн чанарыг invalid болгон, LGOS зангилаагаар дохиолол өгнө. Ингэснээр «чимээгүй» холбооны гэмтэл хамгийн ихдээ 2T<sub>0</sub> хугацаанд илэрнэ — энэ нь уламжлалт зэс утсан хэлхээнд байдаггүй, тасралтгүй өөрийгөө хянах давуу тал юм."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.5. GOOSE-ийн давтан илгээх хугацааны диаграмм (T₁ = 2 мс, T₀ = 1 с)", "h": "Зураг 6.5. GOOSE-ийн давтан илгээх хугацааны диаграмм (T₁ = 2 мс, T₀ = 1 с)"}, {"t": "p", "s": "Жишээ 6.1. GOOSE нийтлэгч T 1=2 мс, T 0=1000 мс, (6.2)-ын дагуу завсрыг хоёр дахин өсгөнө. Үйл явдлын дараах эхний нэг секундэд хэдэн мессеж илгээх, хэдий хугацааны дараа тогтвортой горимд шилжих, тогтвортой үеийн TAL-ыг тодорхойлъё. Мөн 30 IED нэгэн зэрэг (жишээ нь шинын богино холболтын үед) үйл явдал нийтлэхэд кадрын урт 200 байт бол эхний 2 мс-ийн сүлжээний ачааллыг тооцъё.", "h": "<b>Жишээ 6.1.</b> GOOSE нийтлэгч T<sub>1</sub>=2 мс, T<sub>0</sub>=1000 мс, (6.2)-ын дагуу завсрыг хоёр дахин өсгөнө. Үйл явдлын дараах эхний нэг секундэд хэдэн мессеж илгээх, хэдий хугацааны дараа тогтвортой горимд шилжих, тогтвортой үеийн TAL-ыг тодорхойлъё. Мөн 30 IED нэгэн зэрэг (жишээ нь шинын богино холболтын үед) үйл явдал нийтлэхэд кадрын урт 200 байт бол эхний 2 мс-ийн сүлжээний ачааллыг тооцъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. Завсрууд: 2, 4, 8, 16, 32, 64, 128, 256, 512 мс, дараа нь min(1024, 1000)=1000 мс. Илгээх агшин: 0, 2, 6, 14, 30, 62, 126, 254, 510, 1022, 2022 … мс. Эхний секундэд 9 мессеж (sqNum = 0…8) илгээгдэх ба 510 мс-ээс хойш завсар 1000 мс болж тогтворжино (1022 мс-д 10-р мессеж). Тогтвортой үед (6.3)-аар TAL=2⋅1000=2000 мс; холбоо тасарсныг захиалагч хамгийн ихдээ 2 с-ийн дараа илрүүлнэ.", "h": "<i>Бодолт.</i> Завсрууд: 2, 4, 8, 16, 32, 64, 128, 256, 512 мс, дараа нь min(1024, 1000)=1000 мс. Илгээх агшин: 0, 2, 6, 14, 30, 62, 126, 254, 510, 1022, 2022 … мс. Эхний секундэд 9 мессеж (sqNum = 0…8) илгээгдэх ба 510 мс-ээс хойш завсар 1000 мс болж тогтворжино (1022 мс-д 10-р мессеж). Тогтвортой үед (6.3)-аар TAL=2⋅1000=2000 мс; холбоо тасарсныг захиалагч хамгийн ихдээ 2 с-ийн дараа илрүүлнэ.", "x": "ex"}, {"t": "p", "s": "Ачаалал: кадр шугамд преамбул, завсартайгаа 200+20=220 байт. 30 нийтлэгч 2 мс-д тус бүр нэг кадр илгээнэ: B=30⋅220⋅8/0.002=26.4 Мбит/с. Энэ нь 100 Мбит/с-ийн сүлжээний 26 % бөгөөд богино хугацааны «нуранги» (avalanche) ачааллыг сүлжээ даах ёстойг харуулна. Тогтвортой үед ачаалал ердөө 30⋅220⋅8/1=52.8 кбит/с.", "h": "Ачаалал: кадр шугамд преамбул, завсартайгаа 200+20=220 байт. 30 нийтлэгч 2 мс-д тус бүр нэг кадр илгээнэ: B=30⋅220⋅8/0.002=26.4 Мбит/с. Энэ нь 100 Мбит/с-ийн сүлжээний 26 % бөгөөд богино хугацааны «нуранги» (avalanche) ачааллыг сүлжээ даах ёстойг харуулна. Тогтвортой үед ачаалал ердөө 30⋅220⋅8/1=52.8 кбит/с.", "x": "ex"}, {"t": "p", "s": "GOOSE-ийн хэрэглээ: таслах команд (PTRC.Tr → XCBR), таслуурын татгалзлын хамгаалалт (RBRF), шинын «логик блоклолт», бэй хоорондын блоклолт, АДЗ, нөөц тэжээлийг автомат залгах, ачаалал хөнгөрүүлэх. Дэд станц хооронд IEC 61850-90-5-ийн IP-д суурилсан R-GOOSE хэрэглэнэ.", "h": "GOOSE-ийн хэрэглээ: таслах команд (PTRC.Tr → XCBR), таслуурын татгалзлын хамгаалалт (RBRF), шинын «логик блоклолт», бэй хоорондын блоклолт, АДЗ, нөөц тэжээлийг автомат залгах, ачаалал хөнгөрүүлэх. Дэд станц хооронд IEC 61850-90-5-ийн IP-д суурилсан R-GOOSE хэрэглэнэ."}, {"t": "h", "l": 2, "s": "5.4. Түүвэрлэсэн утга (Sampled\nValues)", "h": "5.4. Түүвэрлэсэн утга (Sampled\nValues)"}, {"t": "p", "s": "SV нь MU-ээс гүйдэл, хүчдэлийн агшин утгыг тогтмол давтамжтай, олон хаягт Ethernet кадраар (EtherType 0x88BA, MAC 01‑0C‑CD‑04‑xx‑xx, APPID 0x4000–0x7FFF) нийтэлнэ. Анхны 9-2 стандарт уян хатан тул хэрэгжүүлэлт олон янз болох эрсдэлтэй байсан тул UCA International Users Group 2004 онд 9-2LE удирдамж гаргасан: 4 гүйдэл + 4 хүчдэл, хамгаалалтад нэг үед 80 түүвэр (50 Гц-д 4000 Гц), кадрт нэг ASDU; хэмжилтэд 256 түүвэр, кадрт 8 ASDU; утга бүр 32 битийн бүхэл тоо ба 32 битийн чанарын үгтэй.", "h": "<b>SV</b> нь MU-ээс гүйдэл, хүчдэлийн агшин утгыг тогтмол давтамжтай, олон хаягт Ethernet кадраар (EtherType 0x88BA, MAC 01‑0C‑CD‑04‑xx‑xx, APPID 0x4000–0x7FFF) нийтэлнэ. Анхны 9-2 стандарт уян хатан тул хэрэгжүүлэлт олон янз болох эрсдэлтэй байсан тул UCA International Users Group 2004 онд <b>9-2LE</b> удирдамж гаргасан: 4 гүйдэл + 4 хүчдэл, хамгаалалтад нэг үед 80 түүвэр (50 Гц-д 4000 Гц), кадрт нэг ASDU; хэмжилтэд 256 түүвэр, кадрт 8 ASDU; утга бүр 32 битийн бүхэл тоо ба 32 битийн чанарын үгтэй."}, {"t": "p", "s": "Одоо энэ удирдамжийг IEC 61869-9 (хэмжүүрийн трансформаторын дижитал интерфейс, Лекц 5) орлосон. Түүний санал болгох түүвэрлэлтийн давтамж нь системийн давтамжаас хамааралгүй: хамгаалалт, хэмжилтэд 4800 Гц (нэг кадрт 2 ASDU, 2400 кадр/с), чанарын хэмжилтэд 14 400 Гц (6 ASDU), шууд гүйдлийн хэрэглээнд 96 кГц. Мөн MU-ийн хоцролтын хугацаа (хамгаалалтын хэрэглээнд ихэвчлэн 2 мс хүртэл), smpSynch атрибутаар синхрончлолын төлөв (0 — синхрончлогдоогүй, 1 — орон нутгийн, 2 — глобал цаг) дамжуулах зэргийг тодорхойлсон.", "h": "Одоо энэ удирдамжийг <b>IEC 61869-9</b> (хэмжүүрийн трансформаторын дижитал интерфейс, Лекц 5) орлосон. Түүний санал болгох түүвэрлэлтийн давтамж нь системийн давтамжаас хамааралгүй: хамгаалалт, хэмжилтэд 4800 Гц (нэг кадрт 2 ASDU, 2400 кадр/с), чанарын хэмжилтэд 14 400 Гц (6 ASDU), шууд гүйдлийн хэрэглээнд 96 кГц. Мөн MU-ийн хоцролтын хугацаа (хамгаалалтын хэрэглээнд ихэвчлэн 2 мс хүртэл), smpSynch атрибутаар синхрончлолын төлөв (0 — синхрончлогдоогүй, 1 — орон нутгийн, 2 — глобал цаг) дамжуулах зэргийг тодорхойлсон."}, {"t": "p", "s": "Кадрын давтамж ба урсгал:", "h": "Кадрын давтамж ба урсгал:"}, {"t": "eq", "s": "f кадр=(N f)/(n ASDU) эсвэл f кадр=f s/(n ASDU) (6.4)", "h": "f<sub>кадр</sub>=(N f)/(n<sub>ASDU</sub>) эсвэл f<sub>кадр</sub>=f<sub>s</sub>/(n<sub>ASDU</sub>)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f</mi><mrow><mi>к</mi><mi>а</mi><mi>д</mi><mi>р</mi></mrow></msub><mo>=</mo><mfrac><mrow><mi>N</mi><mspace width=\"0.167em\"></mspace><mi>f</mi></mrow><msub><mi>n</mi><mrow><mi>A</mi><mi>S</mi><mi>D</mi><mi>U</mi></mrow></msub></mfrac><mspace width=\"1.0em\"></mspace><mtext mathvariant=\"normal\">эсвэл</mtext><mspace width=\"1.0em\"></mspace><msub><mi>f</mi><mrow><mi>к</mi><mi>а</mi><mi>д</mi><mi>р</mi></mrow></msub><mo>=</mo><mfrac><msub><mi>f</mi><mi>s</mi></msub><msub><mi>n</mi><mrow><mi>A</mi><mi>S</mi><mi>D</mi><mi>U</mi></mrow></msub></mfrac></mrow></semantics></math>", "n": "6.4"}, {"t": "eq", "s": "B=f кадр (L+20)⋅8, бит/с (6.5)", "h": "B=f<sub>кадр</sub> (L+20)⋅8, бит/с", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi><mo>=</mo><msub><mi>f</mi><mrow><mi>к</mi><mi>а</mi><mi>д</mi><mi>р</mi></mrow></msub><mspace width=\"0.167em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>L</mi><mo>+</mo><mn>20</mn><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>⋅</mo><mn>8</mn><mo>,</mo><mspace width=\"0.222em\"></mspace><mtext mathvariant=\"normal\">бит/с</mtext></mrow></semantics></math>", "n": "6.5"}, {"t": "p", "s": "энд N — нэг үе дэх түүврийн тоо; f — системийн давтамж; f s — түүвэрлэлтийн давтамж; n ASDU — нэг кадр дахь ASDU-ийн тоо; L — кадрын урт (FCS-тэй), байт; 20 — преамбул (8 байт) ба кадр хоорондын завсар (12 байт). 9-2LE кадрын бүтцийг Зураг 6.6-д үзүүлэв.", "h": "энд N — нэг үе дэх түүврийн тоо; f — системийн давтамж; f<sub>s</sub> — түүвэрлэлтийн давтамж; n<sub>ASDU</sub> — нэг кадр дахь ASDU-ийн тоо; L — кадрын урт (FCS-тэй), байт; 20 — преамбул (8 байт) ба кадр хоорондын завсар (12 байт). 9-2LE кадрын бүтцийг Зураг 6.6-д үзүүлэв."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.6. IEC 61850-9-2LE SV кадрын бүтэц (svID 10 тэмдэгттэй үед)", "h": "Зураг 6.6. IEC 61850-9-2LE SV кадрын бүтэц (svID 10 тэмдэгттэй үед)"}, {"t": "p", "s": "Жишээ 6.2. 9-2LE-ийн хамгаалалтын урсгалын кадрын урт, нэг MU-ийн урсгалыг 50 Гц-ийн системд тооцъё. svID 10 тэмдэгттэй. IEC 61869-9-ийн 4800 Гц, 2 ASDU-тэй хувилбартай харьцуулъя.", "h": "<b>Жишээ 6.2.</b> 9-2LE-ийн хамгаалалтын урсгалын кадрын урт, нэг MU-ийн урсгалыг 50 Гц-ийн системд тооцъё. svID 10 тэмдэгттэй. IEC 61869-9-ийн 4800 Гц, 2 ASDU-тэй хувилбартай харьцуулъя.", "x": "ex"}, {"t": "p", "s": "Бодолт. ASDU-ийн агуулга: svID 2+10=12, smpCnt 4, confRev 6, smpSynch 3, seqData 2+8⋅8=66 байт — нийт 91 байт, ASDU-ийн толгойтой 93 байт. seqASDU толгой 2, noASDU 3, savPdu толгой 2 байт нэмбэл APDU 100 байт. Ethernet + VLAN толгой 18, APPID/Length/Reserved 8, FCS 4 байт нэмбэл кадрын урт L=18+8+100+4=130 байт; шугамд 150 байт.", "h": "<i>Бодолт.</i> ASDU-ийн агуулга: svID 2+10=12, smpCnt 4, confRev 6, smpSynch 3, seqData 2+8⋅8=66 байт — нийт 91 байт, ASDU-ийн толгойтой 93 байт. seqASDU толгой 2, noASDU 3, savPdu толгой 2 байт нэмбэл APDU 100 байт. Ethernet + VLAN толгой 18, APPID/Length/Reserved 8, FCS 4 байт нэмбэл кадрын урт L=18+8+100+4=130 байт; шугамд 150 байт.", "x": "ex"}, {"t": "p", "s": "(6.4)-өөр f кадр=80⋅50/1=4000 кадр/с; (6.5)-аар B=4000⋅150⋅8=4.80 Мбит/с.", "h": "(6.4)-өөр f<sub>кадр</sub>=80⋅50/1=4000 кадр/с; (6.5)-аар B=4000⋅150⋅8=4.80 Мбит/с.", "x": "ex"}, {"t": "p", "s": "IEC 61869-9: 2 ASDU (2⋅93=186 байт), толгойн уртын байт нэмэгдэж APDU 195 байт, L=18+8+195+4=225 байт, шугамд 245 байт. f кадр=4800/2=2400 кадр/с, B=2400⋅245⋅8=4.70 Мбит/с. Давтамж 20 % өндөр ч урсгал бараг ижил.", "h": "IEC 61869-9: 2 ASDU (2⋅93=186 байт), толгойн уртын байт нэмэгдэж APDU 195 байт, L=18+8+195+4=225 байт, шугамд 245 байт. f<sub>кадр</sub>=4800/2=2400 кадр/с, B=2400⋅245⋅8=4.70 Мбит/с. Давтамж 20 % өндөр ч урсгал бараг ижил.", "x": "ex"}, {"t": "p", "s": "Процессын шинын ачааллыг төлөвлөхдөө порт бүрийн ачааллын коэффициентыг", "h": "Процессын шинын ачааллыг төлөвлөхдөө порт бүрийн ачааллын коэффициентыг"}, {"t": "eq", "s": "ρ=(∑ jB j)/R≤ρ зөвш (6.6)", "h": "ρ=(∑<sub>j</sub>B<sub>j</sub>)/R≤ρ<sub>зөвш</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ</mi><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>B</mi><mi>j</mi></msub></mrow><mi>R</mi></mfrac><mo>≤</mo><msub><mi>ρ</mi><mrow><mi>з</mi><mi>ө</mi><mi>в</mi><mi>ш</mi></mrow></msub></mrow></semantics></math>", "n": "6.6"}, {"t": "p", "s": "гэж шалгана. Энд R — портын хурд (100 Мбит/с эсвэл 1 Гбит/с); ρ зөвш — зөвшөөрөгдөх ачаалал (GOOSE, PTP, MMS-д нөөц үлдээх үүднээс ихэвчлэн 0.5–0.6). SV-ийн урсгал тасралтгүй, тогтмол тул нэмэлт «нуранги» ачаалал үүсгэдэггүй боловч портын ачааллыг тогтмол эзэлдэг (Зураг 6.7).", "h": "гэж шалгана. Энд R — портын хурд (100 Мбит/с эсвэл 1 Гбит/с); ρ<sub>зөвш</sub> — зөвшөөрөгдөх ачаалал (GOOSE, PTP, MMS-д нөөц үлдээх үүднээс ихэвчлэн 0.5–0.6). SV-ийн урсгал тасралтгүй, тогтмол тул нэмэлт «нуранги» ачаалал үүсгэдэггүй боловч портын ачааллыг тогтмол эзэлдэг (Зураг 6.7)."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.7. Процессын шинын портын ачаалал MU-ийн тооноос хамаарах нь", "h": "Зураг 6.7. Процессын шинын портын ачаалал MU-ийн тооноос хамаарах нь"}, {"t": "p", "s": "Жишээ нь 10 бэйн MU-ээс 9-2LE урсгал хүлээн авах шинын ялгаварт хамгаалалтын 100 Мбит/с-ийн портод (6.6)-аар ρ=10⋅4.8/100=0.48<0.6 хүрэлцэх боловч 14 бэйд ρ=0.672 болж хэтэрнэ; 60 %-ийн хязгаарт 60/4.8=12.5 буюу 12 MU л багтана. Энэ үед 1 Гбит/с порт, шинын хамгаалалтыг секцээр хуваах, эсвэл свичид VLAN, олон хаягт шүүлтүүр тохируулна.", "h": "Жишээ нь 10 бэйн MU-ээс 9-2LE урсгал хүлээн авах шинын ялгаварт хамгаалалтын 100 Мбит/с-ийн портод (6.6)-аар ρ=10⋅4.8/100=0.48&lt;0.6 хүрэлцэх боловч 14 бэйд ρ=0.672 болж хэтэрнэ; 60 %-ийн хязгаарт 60/4.8=12.5 буюу 12 MU л багтана. Энэ үед 1 Гбит/с порт, шинын хамгаалалтыг секцээр хуваах, эсвэл свичид VLAN, олон хаягт шүүлтүүр тохируулна."}, {"t": "h", "l": 1, "s": "6. Дэд станцын харилцааны\nсүлжээ", "h": "6. Дэд станцын харилцааны\nсүлжээ"}, {"t": "h", "l": 2, "s": "6.1. Ethernet, свич, VLAN ба\nприоритет", "h": "6.1. Ethernet, свич, VLAN ба\nприоритет"}, {"t": "p", "s": "Дэд станцын сүлжээг IEC 61850-3 ба IEEE 1613-ын шаардлагыг хангасан үйлдвэрийн свич-ээр байгуулна: −40…+85 °C-д ажиллах, сэнсгүй, EMC-ийн өндөр тэсвэртэй (цахилгаан соронзон импульс, өндөр давтамжийн саад), шууд гүйдлийн тэжээлтэй, хоёр тэжээлийн оролттой. Монголд гадаа шкафын MU, SAMU, свич −40 °C-д асах (cold start) чадвартай байх ёстой.", "h": "Дэд станцын сүлжээг IEC 61850-3 ба IEEE 1613-ын шаардлагыг хангасан <b>үйлдвэрийн свич</b>-ээр байгуулна: −40…+85 °C-д ажиллах, сэнсгүй, EMC-ийн өндөр тэсвэртэй (цахилгаан соронзон импульс, өндөр давтамжийн саад), шууд гүйдлийн тэжээлтэй, хоёр тэжээлийн оролттой. Монголд гадаа шкафын MU, SAMU, свич −40 °C-д асах (cold start) чадвартай байх ёстой."}, {"t": "p", "s": "Свич кадрыг «хадгалж дамжуулах» (store-and-forward) зарчмаар дамжуулна. IEEE 802.1Q шошго нь 12 битийн VLAN дугаар ба 3 битийн приоритет (0–7)-ийг агуулж, свич өндөр приоритеттэй кадрыг (GOOSE, SV) эхэлж илгээнэ. Гэвч илгээгдэж эхэлсэн урт кадрыг тасалдаггүй тул хамгийн муу үед нэг урт кадрын хугацаагаар хүлээнэ.", "h": "Свич кадрыг «хадгалж дамжуулах» (store-and-forward) зарчмаар дамжуулна. <b>IEEE 802.1Q</b> шошго нь 12 битийн VLAN дугаар ба 3 битийн <b>приоритет</b> (0–7)-ийг агуулж, свич өндөр приоритеттэй кадрыг (GOOSE, SV) эхэлж илгээнэ. Гэвч илгээгдэж эхэлсэн урт кадрыг тасалдаггүй тул хамгийн муу үед нэг урт кадрын хугацаагаар хүлээнэ."}, {"t": "p", "s": "Кадрыг сүлжээнд цувуулах (serialization) хугацаа:", "h": "Кадрыг сүлжээнд цувуулах (serialization) хугацаа:"}, {"t": "eq", "s": "t цув=(8 L)/R (6.7)", "h": "t<sub>цув</sub>=(8 L)/R", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t</mi><mrow><mi>ц</mi><mi>у</mi><mi>в</mi></mrow></msub><mo>=</mo><mfrac><mrow><mn>8</mn><mspace width=\"0.167em\"></mspace><mi>L</mi></mrow><mi>R</mi></mfrac></mrow></semantics></math>", "n": "6.7"}, {"t": "p", "s": "Нэг свичээр дамжих хугацаа ба n свичээр дамжих нийт хугацаа:", "h": "Нэг свичээр дамжих хугацаа ба n свичээр дамжих нийт хугацаа:"}, {"t": "eq", "s": "t хоп=t цув+t св+t дар, t b≈∑ k=1^nt хоп,k+t цув (6.8)", "h": "t<sub>хоп</sub>=t<sub>цув</sub>+t<sub>св</sub>+t<sub>дар</sub>, t<sub>b</sub>≈∑<sub>k=1</sub><sup>n</sup>t<sub>хоп,k</sub>+t<sub>цув</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t</mi><mrow><mi>х</mi><mi>о</mi><mi>п</mi></mrow></msub><mo>=</mo><msub><mi>t</mi><mrow><mi>ц</mi><mi>у</mi><mi>в</mi></mrow></msub><mo>+</mo><msub><mi>t</mi><mrow><mi>с</mi><mi>в</mi></mrow></msub><mo>+</mo><msub><mi>t</mi><mrow><mi>д</mi><mi>а</mi><mi>р</mi></mrow></msub><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>t</mi><mi>b</mi></msub><mo>≈</mo><munderover><mo>∑</mo><mrow><mi>k</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>t</mi><mrow><mi>х</mi><mi>о</mi><mi>п</mi><mo>,</mo><mi>k</mi></mrow></msub><mo>+</mo><msub><mi>t</mi><mrow><mi>ц</mi><mi>у</mi><mi>в</mi></mrow></msub></mrow></semantics></math>", "n": "6.8"}, {"t": "p", "s": "энд t св — свичийн дотоод боловсруулалт (ихэвчлэн 2–10 мкс); t дар — дараалалд хүлээх хугацаа (хамгийн муу үед нэг 1522 байтын кадр, 100 Мбит/с-д 123 мкс); сүүлийн гишүүн — сүүлийн свичээс IED хүртэлх холбоос. Оптик кабелийн тархалтын хугацаа (5 мкс/км) дэд станцын хэмжээнд үл тоомсорлохуйц.", "h": "энд t<sub>св</sub> — свичийн дотоод боловсруулалт (ихэвчлэн 2–10 мкс); t<sub>дар</sub> — дараалалд хүлээх хугацаа (хамгийн муу үед нэг 1522 байтын кадр, 100 Мбит/с-д 123 мкс); сүүлийн гишүүн — сүүлийн свичээс IED хүртэлх холбоос. Оптик кабелийн тархалтын хугацаа (5 мкс/км) дэд станцын хэмжээнд үл тоомсорлохуйц."}, {"t": "p", "s": "Жишээ 6.3. Хамгаалалтын IED-ээс SAMU руу илгээх 250 байтын GOOSE таслах кадр 100 Мбит/с-ийн дөрвөн свичээр дамжина. Свичийн боловсруулалт 5 мкс, гаралтын порт бүрт урт кадр (1522 + 20 байт) дамжиж байх хамгийн муу тохиолдлыг авъя. IED-ийн боловсруулалт t a=t c=1 мс бол дамжуулах хугацааг TT6 (3 мс) шаардлагатай харьцуулъя.", "h": "<b>Жишээ 6.3.</b> Хамгаалалтын IED-ээс SAMU руу илгээх 250 байтын GOOSE таслах кадр 100 Мбит/с-ийн дөрвөн свичээр дамжина. Свичийн боловсруулалт 5 мкс, гаралтын порт бүрт урт кадр (1522 + 20 байт) дамжиж байх хамгийн муу тохиолдлыг авъя. IED-ийн боловсруулалт t<sub>a</sub>=t<sub>c</sub>=1 мс бол дамжуулах хугацааг TT6 (3 мс) шаардлагатай харьцуулъя.", "x": "ex"}, {"t": "p", "s": "Бодолт. (6.7)-оор GOOSE кадрын цувуулах хугацаа t цув=8⋅250/10^8=20 мкс; урт кадрын хүлээлт t дар=8⋅1542/10^8=123.4 мкс. (6.8)-аар t хоп=20+5+123.4=148.4 мкс, t b=4⋅148.4+20=613 мкс ≈0.61 мс. (6.1)-ээр t=1+0.61+1=2.61 мс < 3 мс — шаардлага хангагдана. Хүлээлтийн хугацаа давамгайлж байгааг анхаар: 1 Гбит/с-ийн гол сүлжээнд t дар=12.3 мкс болж, t b 0.1 мс хүртэл буурна. Иймээс том дэд станцад гол (backbone) холбоосыг 1 Гбит/с-ээр хийнэ.", "h": "<i>Бодолт.</i> (6.7)-оор GOOSE кадрын цувуулах хугацаа t<sub>цув</sub>=8⋅250/10<sup>8</sup>=20 мкс; урт кадрын хүлээлт t<sub>дар</sub>=8⋅1542/10<sup>8</sup>=123.4 мкс. (6.8)-аар t<sub>хоп</sub>=20+5+123.4=148.4 мкс, t<sub>b</sub>=4⋅148.4+20=613 мкс ≈0.61 мс. (6.1)-ээр t=1+0.61+1=2.61 мс &lt; 3 мс — шаардлага хангагдана. Хүлээлтийн хугацаа давамгайлж байгааг анхаар: 1 Гбит/с-ийн гол сүлжээнд t<sub>дар</sub>=12.3 мкс болж, t<sub>b</sub> 0.1 мс хүртэл буурна. Иймээс том дэд станцад гол (backbone) холбоосыг 1 Гбит/с-ээр хийнэ.", "x": "ex"}, {"t": "h", "l": 2, "s": "6.2. Нөөцлөл: RSTP, PRP, HSR", "h": "6.2. Нөөцлөл: RSTP, PRP, HSR"}, {"t": "p", "s": "Сүлжээний нэг элемент (свич, кабель, порт) гэмтэхэд хамгаалалтын функц тасрахгүй байхын тулд нөөцлөл хэрэглэнэ. Уламжлалт RSTP (IEEE 802.1D Rapid Spanning Tree) цагираг сүлжээ нь гэмтлийн дараа замыг дахин тооцоолж, хэдэн арван мс-ээс хэдэн зуун мс хүртэл хугацаанд сэргэдэг. Энэ хугацаанд GOOSE, SV алдагдана — хамгаалалтын хэрэглээнд хүлээн зөвшөөрөгдөхгүй. Иймээс IEC 62439-3 нь «тэг сэргэлтийн хугацаатай» хоёр протоколыг тодорхойлсон (Зураг 6.8).", "h": "Сүлжээний нэг элемент (свич, кабель, порт) гэмтэхэд хамгаалалтын функц тасрахгүй байхын тулд нөөцлөл хэрэглэнэ. Уламжлалт <b>RSTP</b> (IEEE 802.1D Rapid Spanning Tree) цагираг сүлжээ нь гэмтлийн дараа замыг дахин тооцоолж, хэдэн арван мс-ээс хэдэн зуун мс хүртэл хугацаанд сэргэдэг. Энэ хугацаанд GOOSE, SV алдагдана — хамгаалалтын хэрэглээнд хүлээн зөвшөөрөгдөхгүй. Иймээс <b>IEC 62439-3</b> нь «тэг сэргэлтийн хугацаатай» хоёр протоколыг тодорхойлсон (Зураг 6.8)."}, {"t": "p", "s": "PRP (Parallel Redundancy Protocol) нь хоёр бие даасан, ижил бүтэцтэй (эсвэл өөр бүтэцтэй) LAN A, LAN B ашиглана. Хоёр порттой төхөөрөмж (DANP) кадр бүрийн хуулбарыг хоёр сүлжээнд зэрэг илгээж, кадрын төгсгөлд 6 байтын RCT (Redundancy Control Trailer: дарааллын дугаар, LAN-ы тэмдэг, урт, PRP суффикс) нэмнэ. Хүлээн авагч эхэлж ирснийг авч, хоёрдахийг устгана; нэг порттой төхөөрөмжийг (SAN) RedBox-оор холбоно. Стандарт свич ашиглах боловч сүлжээ хоёр дахин их.", "h": "<b>PRP</b> (Parallel Redundancy Protocol) нь хоёр бие даасан, ижил бүтэцтэй (эсвэл өөр бүтэцтэй) LAN A, LAN B ашиглана. Хоёр порттой төхөөрөмж (DANP) кадр бүрийн хуулбарыг хоёр сүлжээнд зэрэг илгээж, кадрын төгсгөлд 6 байтын RCT (Redundancy Control Trailer: дарааллын дугаар, LAN-ы тэмдэг, урт, PRP суффикс) нэмнэ. Хүлээн авагч эхэлж ирснийг авч, хоёрдахийг устгана; нэг порттой төхөөрөмжийг (SAN) RedBox-оор холбоно. Стандарт свич ашиглах боловч сүлжээ хоёр дахин их."}, {"t": "p", "s": "HSR (High-availability Seamless Redundancy) нь цагираг бүтэцтэй: зангилаа (DANH) бүр кадрыг цагирагийн хоёр чиглэлд илгээж, бусад зангилаа нь кадрыг дамжуулна; эх үүсвэр өөрийн буцаж ирсэн кадрыг устгана. Кадрын эхэнд 6 байтын HSR шошго (EtherType 0x892F) нэмнэ. Свич шаардахгүй ч цагирагт урсгал хоёр дахин өсч, зангилааны тоо ихсэхэд хоцролт өснө (50 зангилаанд cut-through 5 мкс-ээр 0.25 мс). Иймээс HSR-ийг процессын шинд жижиг цагирагаар хэрэглэж, QuadBox-оор холбоно.", "h": "<b>HSR</b> (High-availability Seamless Redundancy) нь цагираг бүтэцтэй: зангилаа (DANH) бүр кадрыг цагирагийн хоёр чиглэлд илгээж, бусад зангилаа нь кадрыг дамжуулна; эх үүсвэр өөрийн буцаж ирсэн кадрыг устгана. Кадрын эхэнд 6 байтын HSR шошго (EtherType 0x892F) нэмнэ. Свич шаардахгүй ч цагирагт урсгал хоёр дахин өсч, зангилааны тоо ихсэхэд хоцролт өснө (50 зангилаанд cut-through 5 мкс-ээр 0.25 мс). Иймээс HSR-ийг процессын шинд жижиг цагирагаар хэрэглэж, QuadBox-оор холбоно."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.8. PRP ба HSR нөөцлөлийн бүтэц (IEC 62439-3)", "h": "Зураг 6.8. PRP ба HSR нөөцлөлийн бүтэц (IEC 62439-3)"}, {"t": "cap", "s": "Хүснэгт 6.6. Сүлжээний нөөцлөлийн аргын харьцуулалт", "h": "Хүснэгт 6.6. Сүлжээний нөөцлөлийн аргын харьцуулалт"}, {"t": "tbl", "s": "", "head": ["Үзүүлэлт", "RSTP", "PRP", "HSR"], "rows": [["Бүтэц", "Цагираг, тор", "Хоёр бие даасан LAN", "Цагираг (свичгүй)"], ["Сэргэх хугацаа", "10–500 мс (бүтцээс)", "0", "0"], ["Нэмэлт тоноглол", "Үгүй", "Хоёр дахь LAN бүхэлдээ", "QuadBox, RedBox"], ["GOOSE, SV-д тохирох", "Хязгаарлагдмал", "Тийм", "Тийм"], ["Хэрэглээ", "Станцын шина (чухал биш)", "Станцын шина, процессын шина", "Процессын шина, бэйн цагираг"]]}, {"t": "p", "s": "Бэлэн байдлын тооцоо. Элементийн бэлэн байдал (availability) нь", "h": "<b>Бэлэн байдлын тооцоо.</b> Элементийн бэлэн байдал (availability) нь"}, {"t": "eq", "s": "A=(MTBF)/(MTBF+MTTR), U=1−A (6.9)", "h": "A=(MTBF)/(MTBF+MTTR), U=1−A", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mo>=</mo><mfrac><mrow><mi>M</mi><mi>T</mi><mi>B</mi><mi>F</mi></mrow><mrow><mi>M</mi><mi>T</mi><mi>B</mi><mi>F</mi><mo>+</mo><mi>M</mi><mi>T</mi><mi>T</mi><mi>R</mi></mrow></mfrac><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>U</mi><mo>=</mo><mn>1</mn><mo>−</mo><mi>A</mi></mrow></semantics></math>", "n": "6.9"}, {"t": "p", "s": "энд MTBF — гэмтэл хоорондын дундаж хугацаа; MTTR — сэргээх дундаж хугацаа; U — бэлэн бус байдал. Цуваа холбогдсон n элементтэй (нэг LAN-ы замын) ба бие даасан хоёр LAN-тай (PRP) системд:", "h": "энд MTBF — гэмтэл хоорондын дундаж хугацаа; MTTR — сэргээх дундаж хугацаа; U — бэлэн бус байдал. Цуваа холбогдсон n элементтэй (нэг LAN-ы замын) ба бие даасан хоёр LAN-тай (PRP) системд:"}, {"t": "eq", "s": "A LAN=∏ i=1^nA i, U PRP=U A U B (6.10)", "h": "A<sub>LAN</sub>=∏<sub>i=1</sub><sup>n</sup>A<sub>i</sub>, U<sub>PRP</sub>=U<sub>A</sub> U<sub>B</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A</mi><mrow><mi>L</mi><mi>A</mi><mi>N</mi></mrow></msub><mo>=</mo><munderover><mo>∏</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><msub><mi>A</mi><mi>i</mi></msub><mo>,</mo><mspace width=\"2.0em\"></mspace><msub><mi>U</mi><mrow><mi>P</mi><mi>R</mi><mi>P</mi></mrow></msub><mo>=</mo><msub><mi>U</mi><mi>A</mi></msub><mspace width=\"0.167em\"></mspace><msub><mi>U</mi><mi>B</mi></msub></mrow></semantics></math>", "n": "6.10"}, {"t": "p", "s": "Жишээ 6.4. IED-ээс SAMU хүртэлх зам гурван свичээр дамжина. Свичийн MTBF=50 жил, MTTR=24 ц (нөөц свичтэй, засварын бригад хүрэх хугацаа орсон). Нэг LAN ба PRP-ийн бэлэн бус байдлыг жилийн тасралтын хугацаагаар харьцуулъя (кабель, IED-ийн портыг тооцохгүй).", "h": "<b>Жишээ 6.4.</b> IED-ээс SAMU хүртэлх зам гурван свичээр дамжина. Свичийн MTBF=50 жил, MTTR=24 ц (нөөц свичтэй, засварын бригад хүрэх хугацаа орсон). Нэг LAN ба PRP-ийн бэлэн бус байдлыг жилийн тасралтын хугацаагаар харьцуулъя (кабель, IED-ийн портыг тооцохгүй).", "x": "ex"}, {"t": "p", "s": "Бодолт. MTBF=50⋅8760=438 000 ц. (6.9)-өөр A=438 000/438 024=0.999945. (6.10)-аар A LAN=0.999945^3=0.999836, U LAN=1.64⋅10^−4 — жилд 1.64⋅10^−4⋅8760⋅60=86 мин холбоогүй. PRP: U PRP=(1.64⋅10^−4)^2=2.7⋅10^−8 — жилд 2.7⋅10^−8⋅8760⋅3600=0.85 с. Нөөцлөл нь бэлэн бус байдлыг 6000 орчим дахин бууруулна. Монголын алслагдсан дэд станцад засварын бригад хүрэх хугацаа урт (MTTR их) тул нөөцлөлийн ач холбогдол улам өснө.", "h": "<i>Бодолт.</i> MTBF=50⋅8760=438 000 ц. (6.9)-өөр A=438 000/438 024=0.999945. (6.10)-аар A<sub>LAN</sub>=0.999945<sup>3</sup>=0.999836, U<sub>LAN</sub>=1.64⋅10<sup>−4</sup> — жилд 1.64⋅10<sup>−4</sup>⋅8760⋅60=86 мин холбоогүй. PRP: U<sub>PRP</sub>=(1.64⋅10<sup>−4</sup>)<sup>2</sup>=2.7⋅10<sup>−8</sup> — жилд 2.7⋅10<sup>−8</sup>⋅8760⋅3600=0.85 с. Нөөцлөл нь бэлэн бус байдлыг 6000 орчим дахин бууруулна. Монголын алслагдсан дэд станцад засварын бригад хүрэх хугацаа урт (MTTR их) тул нөөцлөлийн ач холбогдол улам өснө.", "x": "ex"}, {"t": "h", "l": 1, "s": "7. Цаг синхрончлол", "h": "7. Цаг синхрончлол"}, {"t": "h", "l": 2, "s": "7.1. Шаардлага ба аргууд", "h": "7.1. Шаардлага ба аргууд"}, {"t": "p", "s": "Дэд станцын бүх IED нэг цагтай байх нь үйл явдлын дарааллыг тогтоох (дохиоллын жагсаалт, гэмтлийн шинжилгээ), осциллограммыг хооронд нь харьцуулах, синхрофазор хэмжилт, ялангуяа процессын шинд өөр өөр MU-ийн түүврийг нэгтгэхэд зайлшгүй шаардлагатай. IEC 61850-5 нь цагийн нарийвчлалын ангийг тогтоосон (Хүснэгт 6.7).", "h": "Дэд станцын бүх IED нэг цагтай байх нь үйл явдлын дарааллыг тогтоох (дохиоллын жагсаалт, гэмтлийн шинжилгээ), осциллограммыг хооронд нь харьцуулах, синхрофазор хэмжилт, ялангуяа процессын шинд өөр өөр MU-ийн түүврийг нэгтгэхэд зайлшгүй шаардлагатай. IEC 61850-5 нь цагийн нарийвчлалын ангийг тогтоосон (Хүснэгт 6.7)."}, {"t": "cap", "s": "Хүснэгт 6.7. Цаг синхрончлолын анги ба арга", "h": "Хүснэгт 6.7. Цаг синхрончлолын анги ба арга"}, {"t": "tbl", "s": "", "head": ["Анги", "Нарийвчлал", "Хэрэглээ", "Түгээмэл арга"], "rows": [["TL", "&gt; 10 мс", "Бага чухал үйл явдал", "SNTP"], ["T0", "10 мс", "Үйл явдлын бүртгэл", "SNTP"], ["T1", "1 мс", "Үйл явдлын хугацааны тэмдэг, дохиолол", "SNTP, IRIG-B"], ["T2", "100 мкс", "Чиглэлт харьцуулах хамгаалалт, бүртгэл", "IRIG-B, 1PPS"], ["T3", "25 мкс", "Гармоник, бусад хэмжилт", "IRIG-B, PTP"], ["T4", "4 мкс", "Тоолуур, хамгаалалтын SV (зарим)", "PTP"], ["T5", "1 мкс", "SV-д суурилсан ялгаварт хамгаалалт, синхрофазор", "PTP (IEC 61850-9-3), 1PPS"]]}, {"t": "p", "s": "IRIG-B нь тусдаа кабелиар секунд бүр цагийн код дамжуулж, 1–10 мкс нарийвчлалтай; SNTP нь Ethernet-ээр ~1 мс нарийвчлалтай — үйл явдлын бүртгэлд хангалттай, процессын шинд хангалтгүй; IEEE 1588 PTP нь Ethernet-ээр мкс-ээс бага нарийвчлалд хүрнэ.", "h": "<b>IRIG-B</b> нь тусдаа кабелиар секунд бүр цагийн код дамжуулж, 1–10 мкс нарийвчлалтай; <b>SNTP</b> нь Ethernet-ээр ~1 мс нарийвчлалтай — үйл явдлын бүртгэлд хангалттай, процессын шинд хангалтгүй; <b>IEEE 1588 PTP</b> нь Ethernet-ээр мкс-ээс бага нарийвчлалд хүрнэ."}, {"t": "h", "l": 2, "s": "7.2. PTP-ийн зарчим ба\nэрчим хүчний профайл", "h": "7.2. PTP-ийн зарчим ба\nэрчим хүчний профайл"}, {"t": "p", "s": "PTP-д сүлжээний хамгийн сайн цаг (Grandmaster, ихэвчлэн GNSS хүлээн авагчтай) Sync мессежийг илгээнэ. Мастер Sync илгээсэн t 1, боол (slave) хүлээн авсан t 2, боол Delay_Req илгээсэн t 3, мастер хүлээн авсан t 4 агшинг ашиглан боол өөрийн цагийн зөрүү ба замын хоцролтыг тооцно:", "h": "PTP-д сүлжээний хамгийн сайн цаг (Grandmaster, ихэвчлэн GNSS хүлээн авагчтай) Sync мессежийг илгээнэ. Мастер Sync илгээсэн t<sub>1</sub>, боол (slave) хүлээн авсан t<sub>2</sub>, боол Delay_Req илгээсэн t<sub>3</sub>, мастер хүлээн авсан t<sub>4</sub> агшинг ашиглан боол өөрийн цагийн зөрүү ба замын хоцролтыг тооцно:"}, {"t": "eq", "s": "θ=((t 2−t 1)−(t 4−t 3))/2, d=((t 2−t 1)+(t 4−t 3))/2 (6.11)", "h": "θ=((t<sub>2</sub>−t<sub>1</sub>)−(t<sub>4</sub>−t<sub>3</sub>))/2, d=((t<sub>2</sub>−t<sub>1</sub>)+(t<sub>4</sub>−t<sub>3</sub>))/2", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ</mi><mo>=</mo><mfrac><mrow><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>t</mi><mn>2</mn></msub><mo>−</mo><msub><mi>t</mi><mn>1</mn></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>−</mo><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>t</mi><mn>4</mn></msub><mo>−</mo><msub><mi>t</mi><mn>3</mn></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow><mn>2</mn></mfrac><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>d</mi><mo>=</mo><mfrac><mrow><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>t</mi><mn>2</mn></msub><mo>−</mo><msub><mi>t</mi><mn>1</mn></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>+</mo><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>t</mi><mn>4</mn></msub><mo>−</mo><msub><mi>t</mi><mn>3</mn></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow><mn>2</mn></mfrac></mrow></semantics></math>", "n": "6.11"}, {"t": "p", "s": "энд θ — боолын цагийн зөрүү (offset); d — нэг чиглэлийн хоцролт (хоёр чиглэлд тэнцүү гэж үзнэ). Хугацааны тэмдгийг програм хангамжаар бус, сүлжээний интерфейсийн тоног төхөөрөмжөөр (hardware timestamping) тавьдаг тул нарийвчлал өндөр. Свич нь дамжуулагч цаг (Transparent Clock, TC) байж, кадр свич дотор хүлээсэн хугацааг (residence time) кадрын засварын талбарт нэмнэ; эсвэл хилийн цаг (Boundary Clock, BC) байж, өөрөө боол ба мастер болно.", "h": "энд θ — боолын цагийн зөрүү (offset); d — нэг чиглэлийн хоцролт (хоёр чиглэлд тэнцүү гэж үзнэ). Хугацааны тэмдгийг програм хангамжаар бус, сүлжээний интерфейсийн тоног төхөөрөмжөөр (hardware timestamping) тавьдаг тул нарийвчлал өндөр. Свич нь <b>дамжуулагч цаг</b> (Transparent Clock, TC) байж, кадр свич дотор хүлээсэн хугацааг (residence time) кадрын засварын талбарт нэмнэ; эсвэл <b>хилийн цаг</b> (Boundary Clock, BC) байж, өөрөө боол ба мастер болно."}, {"t": "p", "s": "IEC/IEEE 61850-9-3 нь эрчим хүчний профайлыг тодорхойлсон: Ethernet-ийн 2-р давхаргад (EtherType 0x88F7), «хөрш хоорондын» хоцролтын хэмжилт (peer-to-peer), Grandmaster-ийн алдаа ≤ 250 нс, TC тус бүр ≤ 50 нс, 15 TC дамжсаны дараа нийт ≤ 1 мкс. Grandmaster-ийг нөөцтэй хийж (BMCA алгоритмаар шилжинэ), GNSS алдагдахад IED-ийн цагийг holdover горимд барина. MU-ийн smpSynch синхрончлол алдагдсаныг харуулахад хамгаалалт олон MU-ийн утгыг хослуулдаг функцээ блоклоно.", "h": "<b>IEC/IEEE 61850-9-3</b> нь эрчим хүчний профайлыг тодорхойлсон: Ethernet-ийн 2-р давхаргад (EtherType 0x88F7), «хөрш хоорондын» хоцролтын хэмжилт (peer-to-peer), Grandmaster-ийн алдаа ≤ 250 нс, TC тус бүр ≤ 50 нс, 15 TC дамжсаны дараа нийт ≤ 1 мкс. Grandmaster-ийг нөөцтэй хийж (BMCA алгоритмаар шилжинэ), GNSS алдагдахад IED-ийн цагийг holdover горимд барина. MU-ийн smpSynch синхрончлол алдагдсаныг харуулахад хамгаалалт олон MU-ийн утгыг хослуулдаг функцээ блоклоно."}, {"t": "h", "l": 2, "s": "7.3. Цагийн алдааны нөлөө", "h": "7.3. Цагийн алдааны нөлөө"}, {"t": "p", "s": "Хоёр MU-ийн цагийн зөрүү Δt нь тэдгээрийн хэмжсэн гүйдлийн фазын алдаа болно:", "h": "Хоёр MU-ийн цагийн зөрүү Δt нь тэдгээрийн хэмжсэн гүйдлийн фазын алдаа болно:"}, {"t": "eq", "s": "Δφ=360^∘ f Δt (6.12)", "h": "Δφ=360<sup>∘</sup> f Δt", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><mi>φ</mi><mo>=</mo><msup><mn>360</mn><mo>∘</mo></msup><mspace width=\"0.167em\"></mspace><mi>f</mi><mspace width=\"0.167em\"></mspace><mi>Δ</mi><mi>t</mi></mrow></semantics></math>", "n": "6.12"}, {"t": "p", "s": "Ижил хэмжээтэй, нэг фазтай байх ёстой хоёр гүйдлийн ялгаварт хамгаалалтад үүсэх хуурамч ялгаварт гүйдэл ба синхрофазорын нийт векторын алдаа (TVE)-д оруулах хувь нэмэр:", "h": "Ижил хэмжээтэй, нэг фазтай байх ёстой хоёр гүйдлийн ялгаварт хамгаалалтад үүсэх хуурамч ялгаварт гүйдэл ба синхрофазорын нийт векторын алдаа (TVE)-д оруулах хувь нэмэр:"}, {"t": "eq", "s": "I д/I=2sinΔφ/2, TVE≈2πf Δt (6.13)", "h": "I<sub>д</sub>/I=2sinΔφ/2, TVE≈2πf Δt", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><msub><mi>I</mi><mi>д</mi></msub><mi>I</mi></mfrac><mo>=</mo><mn>2</mn><mo>sin</mo><mfrac><mrow><mi>Δ</mi><mi>φ</mi></mrow><mn>2</mn></mfrac><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>T</mi><mi>V</mi><mi>E</mi><mo>≈</mo><mn>2</mn><mi>π</mi><mi>f</mi><mspace width=\"0.167em\"></mspace><mi>Δ</mi><mi>t</mi></mrow></semantics></math>", "n": "6.13"}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.9. Синхрончлолын алдаанаас үүсэх фазын алдаа ба хуурамч ялгаварт гүйдэл (50 Гц)", "h": "Зураг 6.9. Синхрончлолын алдаанаас үүсэх фазын алдаа ба хуурамч ялгаварт гүйдэл (50 Гц)"}, {"t": "p", "s": "Жишээ 6.5. 50 Гц-ийн системд ялгаварт хамгаалалтын хоёр MU-ийн цагийн зөрүү (а) 1 мкс (PTP), (б) 1 мс (SNTP) бол фазын алдаа, хуурамч ялгаварт гүйдлийг тооцъё. Синхрофазор хэмжилтийн TVE ≤ 1 % шаардлагыг хангах цагийн алдааны хязгаар, IEC 61850-9-3-ийн 15 TC-тэй сүлжээний цагийн алдааны хамгийн муу утгыг тодорхойлъё.", "h": "<b>Жишээ 6.5.</b> 50 Гц-ийн системд ялгаварт хамгаалалтын хоёр MU-ийн цагийн зөрүү (а) 1 мкс (PTP), (б) 1 мс (SNTP) бол фазын алдаа, хуурамч ялгаварт гүйдлийг тооцъё. Синхрофазор хэмжилтийн TVE ≤ 1 % шаардлагыг хангах цагийн алдааны хязгаар, IEC 61850-9-3-ийн 15 TC-тэй сүлжээний цагийн алдааны хамгийн муу утгыг тодорхойлъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. (а) (6.12)-оор Δφ=360⋅50⋅10^−6=0.018^∘; (6.13)-аар I д/I=2sin(0.009^∘)=3.1⋅10^−4 буюу 0.031 % — үл тоомсорлохуйц. (б) Δφ=360⋅50⋅10^−3=18^∘, I д/I=2sin9^∘=0.313 буюу 31 % — хэвийн ачааллын үед хамгаалалт буруу ажиллах аюултай. TVE = 1 %: Δt=0.01/(2π⋅50)=31.8 мкс. 15 TC-тэй сүлжээ: хамгийн муу утга 250+15⋅50=1000 нс = 1 мкс (T5 анги). Санамсаргүй, хамааралгүй алдаа гэж үзвэл квадрат нийлбэрээр √(250^2+15⋅50^2)=316 нс.", "h": "<i>Бодолт.</i> (а) (6.12)-оор Δφ=360⋅50⋅10<sup>−6</sup>=0.018<sup>∘</sup>; (6.13)-аар I<sub>д</sub>/I=2sin(0.009<sup>∘</sup>)=3.1⋅10<sup>−4</sup> буюу 0.031 % — үл тоомсорлохуйц. (б) Δφ=360⋅50⋅10<sup>−3</sup>=18<sup>∘</sup>, I<sub>д</sub>/I=2sin9<sup>∘</sup>=0.313 буюу 31 % — хэвийн ачааллын үед хамгаалалт буруу ажиллах аюултай. TVE = 1 %: Δt=0.01/(2π⋅50)=31.8 мкс. 15 TC-тэй сүлжээ: хамгийн муу утга 250+15⋅50=1000 нс = 1 мкс (T5 анги). Санамсаргүй, хамааралгүй алдаа гэж үзвэл квадрат нийлбэрээр √(250<sup>2</sup>+15⋅50<sup>2</sup>)=316 нс.", "x": "ex"}, {"t": "h", "l": 1, "s": "8. Дэд станцын\nавтоматжуулалтын систем ба SCADA", "h": "8. Дэд станцын\nавтоматжуулалтын систем ба SCADA"}, {"t": "h", "l": 2, "s": "8.1. SAS-ийн функц ба HMI", "h": "8.1. SAS-ийн функц ба HMI"}, {"t": "p", "s": "Дэд станцын автоматжуулалтын систем (SAS) нь хоёрдогч тоноглолыг нэгтгэж: блоклолттой удирдлага, хэмжилт, дохиолол, үйл явдлын бүртгэл, тохируулгын бүлэг солих, осциллограмм цуглуулах, хүчдэлийн автомат тохируулга, синхрончлолыг шалгах, ачаалал хөнгөрүүлэх, тоноглолын хяналт (Лекц 10), диспетчерийн төвтэй холбох функцийг гүйцэтгэнэ.", "h": "<b>Дэд станцын автоматжуулалтын систем</b> (SAS) нь хоёрдогч тоноглолыг нэгтгэж: блоклолттой удирдлага, хэмжилт, дохиолол, үйл явдлын бүртгэл, тохируулгын бүлэг солих, осциллограмм цуглуулах, хүчдэлийн автомат тохируулга, синхрончлолыг шалгах, ачаалал хөнгөрүүлэх, тоноглолын хяналт (Лекц 10), диспетчерийн төвтэй холбох функцийг гүйцэтгэнэ."}, {"t": "p", "s": "HMI нь мнемосхем, бэйн дүрс, ач холбогдлоор ангилсан дохиолол, үйл явдал, чиг хандлагын графикийг харуулна; хоёр сервертэй (hot standby) хийж, BCU-ийн урд самбараас орон нутгийн удирдлагыг хадгална.", "h": "<b>HMI</b> нь мнемосхем, бэйн дүрс, ач холбогдлоор ангилсан дохиолол, үйл явдал, чиг хандлагын графикийг харуулна; хоёр сервертэй (hot standby) хийж, BCU-ийн урд самбараас орон нутгийн удирдлагыг хадгална."}, {"t": "p", "s": "Гарц (gateway) нь IEC 61850-ийн клиент байж IED-ээс тайлан авч, диспетчерийн төвд IEC 60870-5-104-ийн серверийн үүрэг гүйцэтгэнэ; нөөцтэй хоёр гарцыг хоёр өөр сувгаар (оптик, радио/хиймэл дагуул) холбоно.", "h": "<b>Гарц</b> (gateway) нь IEC 61850-ийн клиент байж IED-ээс тайлан авч, диспетчерийн төвд IEC 60870-5-104-ийн серверийн үүрэг гүйцэтгэнэ; нөөцтэй хоёр гарцыг хоёр өөр сувгаар (оптик, радио/хиймэл дагуул) холбоно."}, {"t": "h", "l": 2, "s": "8.2. Алсын удирдлагын\nпротоколууд", "h": "8.2. Алсын удирдлагын\nпротоколууд"}, {"t": "p", "s": "Монголд Үндэсний диспетчерийн төв (ҮДТ), бүсийн диспетчерийн төвүүд дэд станцаас IEC 60870-5-101/104-өөр, түгээх сүлжээний зарим систем DNP3-аар мэдээлэл авдаг; ирээдүйд IEC 61850-90-2-оор шууд холбож болно (Хүснэгт 6.8).", "h": "Монголд Үндэсний диспетчерийн төв (ҮДТ), бүсийн диспетчерийн төвүүд дэд станцаас IEC 60870-5-101/104-өөр, түгээх сүлжээний зарим систем DNP3-аар мэдээлэл авдаг; ирээдүйд IEC 61850-90-2-оор шууд холбож болно (Хүснэгт 6.8)."}, {"t": "cap", "s": "Хүснэгт 6.8. Дэд станц–диспетчерийн төвийн протоколын харьцуулалт", "h": "Хүснэгт 6.8. Дэд станц–диспетчерийн төвийн протоколын харьцуулалт"}, {"t": "tbl", "s": "", "head": ["Үзүүлэлт", "IEC 60870-5-101", "IEC 60870-5-104", "DNP3 (IEEE 1815)", "IEC 61850-90-2"], "rows": [["Суваг", "Цуваа (V.24, RS-485, модем)", "TCP/IP, порт 2404", "Цуваа эсвэл TCP/UDP 20000", "TCP/IP (MMS), WAN"], ["Өгөгдлийн загвар", "Хаягт объект (IOA), төрлийн дугаар", "101-тэй ижил", "Анги, индекс бүхий цэг", "Объект хандлагат (LN/DO)"], ["Өөрийгөө тайлбарлах", "Үгүй", "Үгүй", "Хязгаарлагдмал", "Тийм (SCL)"], ["Хугацааны тэмдэг", "CP56Time2a (мс)", "CP56Time2a (мс)", "48 бит (мс)", "UTC, мкс-ийн нарийвчлалтай"], ["Кибер хамгаалалт", "IEC 62351-5", "IEC 62351-3, -5 (TLS)", "Secure Authentication v5/6", "IEC 62351-3, -4, -6"], ["Хэрэглээ", "Хуучин RTU, бага хурдтай суваг", "Европ, Ази, Монгол — дамжуулах сүлжээ", "Хойд Америк, түгээх сүлжээ", "Шинэ дижитал систем"]]}, {"t": "p", "s": "IEC 60870-5-104-ийн мэдээллийн нэгж (APDU) нь 6 байтын APCI (эхлэлийн тэмдэг 0x68, урт, 4 байтын удирдлагын талбар), 6 байтын ASDU-ийн толгой (төрлийн дугаар, VSQ, шалтгаан 2 байт, нийтлэг хаяг 2 байт), мэдээллийн объектуудаас бүрдэнэ. Объект бүр 3 байтын хаяг (IOA), утга, чанарын байт, шаардлагатай бол 7 байтын CP56Time2a хугацааны тэмдэгтэй. Нэг ASDU-д ижил төрлийн хэд хэдэн объект багтааж болох ба APDU-ийн урт 255 байтаас хэтрэхгүй:", "h": "IEC 60870-5-104-ийн мэдээллийн нэгж (APDU) нь 6 байтын APCI (эхлэлийн тэмдэг 0x68, урт, 4 байтын удирдлагын талбар), 6 байтын ASDU-ийн толгой (төрлийн дугаар, VSQ, шалтгаан 2 байт, нийтлэг хаяг 2 байт), мэдээллийн объектуудаас бүрдэнэ. Объект бүр 3 байтын хаяг (IOA), утга, чанарын байт, шаардлагатай бол 7 байтын CP56Time2a хугацааны тэмдэгтэй. Нэг ASDU-д ижил төрлийн хэд хэдэн объект багтааж болох ба APDU-ийн урт 255 байтаас хэтрэхгүй:"}, {"t": "eq", "s": "L APDU=6+6+n (3+l obj)≤255 (6.14)", "h": "L<sub>APDU</sub>=6+6+n (3+l<sub>obj</sub>)≤255", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L</mi><mrow><mi>A</mi><mi>P</mi><mi>D</mi><mi>U</mi></mrow></msub><mo>=</mo><mn>6</mn><mo>+</mo><mn>6</mn><mo>+</mo><mi>n</mi><mspace width=\"0.167em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mn>3</mn><mo>+</mo><msub><mi>l</mi><mrow><mi>o</mi><mi>b</mi><mi>j</mi></mrow></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mo>≤</mo><mn>255</mn></mrow></semantics></math>", "n": "6.14"}, {"t": "p", "s": "энд n — объектын тоо; l obj — объектын утга, чанар, хугацааны тэмдгийн урт. Хэмжилтийг богино хөвөгч таслалтай тоо, хугацааны тэмдэгтэйгээр (төрөл 36, M_ME_TF_1) дамжуулахад l obj=4+1+7=12 байт.", "h": "энд n — объектын тоо; l<sub>obj</sub> — объектын утга, чанар, хугацааны тэмдгийн урт. Хэмжилтийг богино хөвөгч таслалтай тоо, хугацааны тэмдэгтэйгээр (төрөл 36, M_ME_TF_1) дамжуулахад l<sub>obj</sub>=4+1+7=12 байт."}, {"t": "p", "s": "Жишээ 6.6. 220 кВ-ын дэд станцаас ҮДТ руу 2000 хэмжилтийг IEC 60870-5-104-ийн төрөл 36-аар, мэдрэмжгүй бүсээр (deadband) дамжуулна. Хэмжилт бүр дунджаар 5 с-д нэг удаа өөрчлөгдөнө. Объект бүрийг тусдаа APDU-ээр, мөн нэг APDU-д хамгийн олон объект багтаан илгээх хувилбарын урсгалыг тооцъё (TCP/IP толгой 40 байт, Ethernet 18 байт).", "h": "<b>Жишээ 6.6.</b> 220 кВ-ын дэд станцаас ҮДТ руу 2000 хэмжилтийг IEC 60870-5-104-ийн төрөл 36-аар, мэдрэмжгүй бүсээр (deadband) дамжуулна. Хэмжилт бүр дунджаар 5 с-д нэг удаа өөрчлөгдөнө. Объект бүрийг тусдаа APDU-ээр, мөн нэг APDU-д хамгийн олон объект багтаан илгээх хувилбарын урсгалыг тооцъё (TCP/IP толгой 40 байт, Ethernet 18 байт).", "x": "ex"}, {"t": "p", "s": "Бодолт. Үйл явдлын тоо 2000/5=400 1/с. (6.14)-өөр нэг объекттой APDU: 6+6+15=27 байт; кадр 27+40+18=85 байт; урсгал 400⋅85⋅8=272 кбит/с. Нэг APDU-д багтах объект: n≤(255−12)/15=16.2 ⇒ 16; APDU 6+6+16⋅15=252 байт, кадр 310 байт, 400/16=25 кадр/с, урсгал 25⋅310⋅8=62 кбит/с. Нэгтгэн илгээх нь урсгалыг 4.4 дахин бууруулна. Энэ нь хиймэл дагуул, радиогоор холбогдсон алслагдсан дэд станцад чухал.", "h": "<i>Бодолт.</i> Үйл явдлын тоо 2000/5=400 1/с. (6.14)-өөр нэг объекттой APDU: 6+6+15=27 байт; кадр 27+40+18=85 байт; урсгал 400⋅85⋅8=272 кбит/с. Нэг APDU-д багтах объект: n≤(255−12)/15=16.2 ⇒ 16; APDU 6+6+16⋅15=252 байт, кадр 310 байт, 400/16=25 кадр/с, урсгал 25⋅310⋅8=62 кбит/с. Нэгтгэн илгээх нь урсгалыг 4.4 дахин бууруулна. Энэ нь хиймэл дагуул, радиогоор холбогдсон алслагдсан дэд станцад чухал.", "x": "ex"}, {"t": "h", "l": 1, "s": "9. GOOSE-ээр блоклолт", "h": "9. GOOSE-ээр блоклолт"}, {"t": "p", "s": "Блоклолт (interlocking) нь коммутацын аппаратыг аюултай үйлдлээс хамгаална: ачаалалтай салгуурыг таслах, газардуулагч залгаатай үед хүчдэл өгөх, хүчдэлтэй хэсэгт газардуулагч залгах. Уламжлалт дэд станцад блоклолтыг аппаратуудын туслах контактыг цуваа/зэрэгцээ холбосон зэс утсан хэлхээ, цахилгаан соронзон түгжээгээр хийдэг байв.", "h": "<b>Блоклолт</b> (interlocking) нь коммутацын аппаратыг аюултай үйлдлээс хамгаална: ачаалалтай салгуурыг таслах, газардуулагч залгаатай үед хүчдэл өгөх, хүчдэлтэй хэсэгт газардуулагч залгах. Уламжлалт дэд станцад блоклолтыг аппаратуудын туслах контактыг цуваа/зэрэгцээ холбосон зэс утсан хэлхээ, цахилгаан соронзон түгжээгээр хийдэг байв."}, {"t": "p", "s": "IEC 61850-д блоклолтын логикийг CILO зангилаа гүйцэтгэнэ (Зураг 6.10). CILO нь өөрийн бэйн болон бусад бэйн аппаратын байрлалыг GOOSE-ээр хүлээн авч, логик нөхцөлөөр EnaOpn (таслахыг зөвшөөрөх), EnaCls (залгахыг зөвшөөрөх) гаргана. CSWI нь операторын команд ирэхэд эдгээрийг шалгаад, зөвшөөрөлгүй бол командыг татгалзана. Жишээ нь шинын салгуур QB1-ийг залгах нөхцөл: тухайн бэйн таслуур QA1 тасархай, шугамын газардуулагч QC1 тасархай, шинын газардуулагч (өөр бэйд) тасархай.", "h": "IEC 61850-д блоклолтын логикийг <b>CILO</b> зангилаа гүйцэтгэнэ (Зураг 6.10). CILO нь өөрийн бэйн болон бусад бэйн аппаратын байрлалыг GOOSE-ээр хүлээн авч, логик нөхцөлөөр EnaOpn (таслахыг зөвшөөрөх), EnaCls (залгахыг зөвшөөрөх) гаргана. CSWI нь операторын команд ирэхэд эдгээрийг шалгаад, зөвшөөрөлгүй бол командыг татгалзана. Жишээ нь шинын салгуур QB1-ийг залгах нөхцөл: тухайн бэйн таслуур QA1 тасархай, шугамын газардуулагч QC1 тасархай, шинын газардуулагч (өөр бэйд) тасархай."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 6.10. GOOSE-ээр хэрэгжүүлэх бэйн салгуурын блоклолтын логик", "h": "Зураг 6.10. GOOSE-ээр хэрэгжүүлэх бэйн салгуурын блоклолтын логик"}, {"t": "p", "s": "Гол зарчим: мэдээлэл эргэлзээтэй бол хориглох — GOOSE-ийн чанар invalid, TAL хэтэрсэн, test тэмдэгтэй, байрлал 00/11 бол CILO зөвшөөрөл өгөхгүй. Блоклолтыг тойрох нь тусгай эрх, бүртгэлтэй байх ба логикийг BCU-д заавал хэрэгжүүлснээр станцын сервер гэмтсэн үед ч аюулгүй байдал хадгалагдана.", "h": "Гол зарчим: <b>мэдээлэл эргэлзээтэй бол хориглох</b> — GOOSE-ийн чанар invalid, TAL хэтэрсэн, test тэмдэгтэй, байрлал 00/11 бол CILO зөвшөөрөл өгөхгүй. Блоклолтыг тойрох нь тусгай эрх, бүртгэлтэй байх ба логикийг BCU-д заавал хэрэгжүүлснээр станцын сервер гэмтсэн үед ч аюулгүй байдал хадгалагдана."}, {"t": "p", "s": "GOOSE-ээр блоклолт нь кабелийг эрс бууруулж, логикийг симуляцаар шалгах боломж олгох боловч өөрчлөлт бүрийг SCD-ийн хувилбартай уялдуулан бүрэн туршина.", "h": "GOOSE-ээр блоклолт нь кабелийг эрс бууруулж, логикийг симуляцаар шалгах боломж олгох боловч өөрчлөлт бүрийг SCD-ийн хувилбартай уялдуулан бүрэн туршина."}, {"t": "h", "l": 1, "s": "10. Туршилт ба ашиглалтад\nоруулалт", "h": "10. Туршилт ба ашиглалтад\nоруулалт"}, {"t": "h", "l": 2, "s": "10.1. Туршилтын шат", "h": "10.1. Туршилтын шат"}, {"t": "p", "s": "Дижитал дэд станцад «утас шалгах» оронд өгөгдлийн холбоос, сүлжээ, тохируулгын файлыг шалгана. Шатууд: тохирлын туршилт (IEC 61850-10, IED тус бүрийг гэрчилгээжүүлсэн лабораторид); FAT — бүх системийг үйлдвэрт SCD-ийн дагуу угсарч, MU-д дижитал SV өгч, GOOSE, блоклолт, HMI, гарцыг шалгах; SAT — дэд станцад анхдагч тоноглолтой хамт (ГТ-ийн туйл, MU-ийн нарийвчлал, таслуурын ажиллагаа, диспетчерийн төвтэй холбоо); ашиглалтын үеийн хэсэгчилсэн туршилт.", "h": "Дижитал дэд станцад «утас шалгах» оронд өгөгдлийн холбоос, сүлжээ, тохируулгын файлыг шалгана. Шатууд: <b>тохирлын туршилт</b> (IEC 61850-10, IED тус бүрийг гэрчилгээжүүлсэн лабораторид); <b>FAT</b> — бүх системийг үйлдвэрт SCD-ийн дагуу угсарч, MU-д дижитал SV өгч, GOOSE, блоклолт, HMI, гарцыг шалгах; <b>SAT</b> — дэд станцад анхдагч тоноглолтой хамт (ГТ-ийн туйл, MU-ийн нарийвчлал, таслуурын ажиллагаа, диспетчерийн төвтэй холбоо); <b>ашиглалтын үеийн</b> хэсэгчилсэн туршилт."}, {"t": "p", "s": "Туршилтад SV/GOOSE нийтлэх дижитал туршилтын төхөөрөмж, сүлжээний анализатор хэрэглэж, тохируулгыг SCD-ээс автоматаар үүсгэнэ.", "h": "Туршилтад SV/GOOSE нийтлэх дижитал туршилтын төхөөрөмж, сүлжээний анализатор хэрэглэж, тохируулгыг SCD-ээс автоматаар үүсгэнэ."}, {"t": "h", "l": 2, "s": "10.2. Туршилтын горим ба\nсимуляц", "h": "10.2. Туршилтын горим ба\nсимуляц"}, {"t": "p", "s": "Ашиглалтад байгаа дэд станцад нэг IED-ийг туршихдаа бусад IED-ийг аюулгүй байлгах механизмыг IEC 61850 Ed.2 тодорхойлсон:", "h": "Ашиглалтад байгаа дэд станцад нэг IED-ийг туршихдаа бусад IED-ийг аюулгүй байлгах механизмыг IEC 61850 Ed.2 тодорхойлсон:"}, {"t": "p", "s": "Mod/Beh = test — LN туршилтын горимд ажиллаж, нийтлэх мэдээллийн q.test = TRUE болно. Хэвийн горимд ажиллаж буй захиалагч ийм мессежийг үйлдлийн логикт ашиглахгүй; харин өөрөө test горимд байгаа захиалагч хүлээн авч боловсруулна.", "h": "• <b>Mod/Beh = test</b> — LN туршилтын горимд ажиллаж, нийтлэх мэдээллийн q.test = TRUE болно. Хэвийн горимд ажиллаж буй захиалагч ийм мессежийг үйлдлийн логикт ашиглахгүй; харин өөрөө test горимд байгаа захиалагч хүлээн авч боловсруулна."}, {"t": "p", "s": "Mod/Beh = test/blocked — LN бүх функцээ гүйцэтгэх боловч физик гаралт (таслуурын ороомог) руу команд өгөхгүй. Хамгаалалтын ажиллагааг бодит таслуургүйгээр шалгахад хэрэглэнэ.", "h": "• <b>Mod/Beh = test/blocked</b> — LN бүх функцээ гүйцэтгэх боловч физик гаралт (таслуурын ороомог) руу команд өгөхгүй. Хамгаалалтын ажиллагааг бодит таслуургүйгээр шалгахад хэрэглэнэ."}, {"t": "p", "s": "Симуляц (LPHD.Sim = TRUE) — IED нь бодит GOOSE/SV-ийн оронд simulation тэмдэгтэй (GOOSE-д simulation бит, SV-д Reserved1 талбарын бит) туршилтын мессежийг хүлээн авна. Туршилтын төхөөрөмж бодит MU, IED-ийг «дуурайж» мессеж илгээх ба зөвхөн симуляцын горимд байгаа IED түүнийг ашиглана.", "h": "• <b>Симуляц</b> (LPHD.Sim = TRUE) — IED нь бодит GOOSE/SV-ийн оронд simulation тэмдэгтэй (GOOSE-д simulation бит, SV-д Reserved1 талбарын бит) туршилтын мессежийг хүлээн авна. Туршилтын төхөөрөмж бодит MU, IED-ийг «дуурайж» мессеж илгээх ба зөвхөн симуляцын горимд байгаа IED түүнийг ашиглана."}, {"t": "p", "s": "Тусгаарлалт — туршиж буй бэйн MU, SAMU-г сүлжээнээс логикоор (VLAN, свичийн портыг хаах) тусгаарлах; LGOS, LSVS зангилаагаар захиалгын төлвийг хянах.", "h": "• <b>Тусгаарлалт</b> — туршиж буй бэйн MU, SAMU-г сүлжээнээс логикоор (VLAN, свичийн портыг хаах) тусгаарлах; LGOS, LSVS зангилаагаар захиалгын төлвийг хянах."}, {"t": "p", "s": "Туршилтын дараа «туршилтын горимд мартагдсан» IED үлдээгүйг HMI-д тусгай дохиогоор хянана.", "h": "Туршилтын дараа «туршилтын горимд мартагдсан» IED үлдээгүйг HMI-д тусгай дохиогоор хянана."}, {"t": "h", "l": 2, "s": "10.3. Монголд нэвтрүүлэх\nасуудал", "h": "10.3. Монголд нэвтрүүлэх\nасуудал"}, {"t": "p", "s": "Монголын 220/110 кВ-ын шинэ дэд станцуудад станцын шина (MMS, GOOSE) нэвтэрч, ҮДТ-тэй IEC 60870-5-104-өөр холбогдож байна. Процессын шинтай дэд станцад шилжихэд: (1) олон үйлдвэрлэгчийн SCD-г удирдах инженерийн чадавх; (2) −40 °C-д ажиллах MU, SAMU, свичийн шаардлага; (3) GNSS-ийн нөөц, holdover; (4) кибер аюулгүй байдал (Лекц 12); (5) ажилтны сургалт; (6) үндэсний норматив баримтыг шинэчлэх шаардлагатай. Эхлээд станцын шинаас эхэлж, дараа нь «дижитал бэй»-ийг туршилтын журмаар нэвтрүүлэх нь эрсдэл багатай.", "h": "Монголын 220/110 кВ-ын шинэ дэд станцуудад станцын шина (MMS, GOOSE) нэвтэрч, ҮДТ-тэй IEC 60870-5-104-өөр холбогдож байна. Процессын шинтай дэд станцад шилжихэд: (1) олон үйлдвэрлэгчийн SCD-г удирдах инженерийн чадавх; (2) −40 °C-д ажиллах MU, SAMU, свичийн шаардлага; (3) GNSS-ийн нөөц, holdover; (4) кибер аюулгүй байдал (Лекц 12); (5) ажилтны сургалт; (6) үндэсний норматив баримтыг шинэчлэх шаардлагатай. Эхлээд станцын шинаас эхэлж, дараа нь «дижитал бэй»-ийг туршилтын журмаар нэвтрүүлэх нь эрсдэл багатай."}, {"t": "h", "l": 1, "s": "Нэр томьёо", "h": "Нэр томьёо"}, {"t": "tbl", "s": "", "head": ["Монгол", "Англи", "Орос"], "rows": [["Ухаалаг электрон төхөөрөмж", "Intelligent electronic device (IED)", "Интеллектуальное электронное устройство"], ["Логик төхөөрөмж", "Logical device (LD)", "Логическое устройство"], ["Логик зангилаа", "Logical node (LN)", "Логический узел"], ["Өгөгдлийн объект / атрибут", "Data object / data attribute", "Объект данных / атрибут данных"], ["Нийтлэг өгөгдлийн анги", "Common data class (CDC)", "Общий класс данных"], ["Тохируулгын тодорхойлолтын хэл", "Substation configuration language (SCL)", "Язык описания конфигурации подстанции"], ["Нийтлэгч / захиалагч", "Publisher / subscriber", "Издатель / подписчик"], ["Түүвэрлэсэн утга", "Sampled values (SV)", "Мгновенные значения (выборки)"], ["Нэгтгэх төхөөрөмж", "Merging unit (MU)", "Устройство сопряжения с шиной процесса (ПАС)"], ["Зэрэгцээ нөөцлөлийн протокол", "Parallel redundancy protocol (PRP)", "Протокол параллельного резервирования"], ["Нарийн цагийн протокол", "Precision time protocol (PTP)", "Протокол точного времени"], ["Блоклолт", "Interlocking", "Оперативная блокировка"], ["Дэд станцын автоматжуулалтын систем", "Substation automation system (SAS)", "АСУ ТП подстанции"]]}, {"t": "h", "l": 1, "s": "Дүгнэлт", "h": "Дүгнэлт"}, {"t": "p", "s": "IEC 61850 нь харилцааны протокол төдийгүй функцийн загварчлал, нэрлэлт, SCL-ийн инженерчлэл, гүйцэтгэлийн шаардлага, туршилтыг цогцоор нь тодорхойлж, өөр үйлдвэрлэгчийн IED-ийн харилцан ажиллах чадварыг хангадаг.", "h": "• IEC 61850 нь харилцааны протокол төдийгүй функцийн загварчлал, нэрлэлт, SCL-ийн инженерчлэл, гүйцэтгэлийн шаардлага, туршилтыг цогцоор нь тодорхойлж, өөр үйлдвэрлэгчийн IED-ийн харилцан ажиллах чадварыг хангадаг."}, {"t": "p", "s": "Дижитал дэд станц станц–бэй–процессын гурван түвшинтэй; процессын шина нь MU, SAMU-г ашиглан зэс хяналтын кабелийг оптик Ethernet-ээр орлуулна.", "h": "• Дижитал дэд станц станц–бэй–процессын гурван түвшинтэй; процессын шина нь MU, SAMU-г ашиглан зэс хяналтын кабелийг оптик Ethernet-ээр орлуулна."}, {"t": "p", "s": "Өгөгдлийн загвар IED → LD → LN → DO → DA шатлалтай; LN-ийн бүлэг (P, C, X, M, T…), CDC, функциональ хязгаарлалт нь өгөгдлийн утгыг стандартчилна.", "h": "• Өгөгдлийн загвар IED → LD → LN → DO → DA шатлалтай; LN-ийн бүлэг (P, C, X, M, T…), CDC, функциональ хязгаарлалт нь өгөгдлийн утгыг стандартчилна."}, {"t": "p", "s": "MMS тайлан (100–500 мс) станцын түвшинд, GOOSE (≤ 3 мс, давтан илгээлт, stNum/sqNum, TAL) хамгаалалт, блоклолтод, SV (4000–4800 кадр/с, ~4.8 Мбит/с/MU) процессын шинд хэрэглэгдэнэ.", "h": "• MMS тайлан (100–500 мс) станцын түвшинд, GOOSE (≤ 3 мс, давтан илгээлт, stNum/sqNum, TAL) хамгаалалт, блоклолтод, SV (4000–4800 кадр/с, ~4.8 Мбит/с/MU) процессын шинд хэрэглэгдэнэ."}, {"t": "p", "s": "Сүлжээний саатлыг свичийн дараалал давамгайлдаг; PRP/HSR (IEC 62439-3) нь тэг сэргэлтийн хугацаатай нөөцлөлөөр бэлэн бус байдлыг мянга дахин бууруулна.", "h": "• Сүлжээний саатлыг свичийн дараалал давамгайлдаг; PRP/HSR (IEC 62439-3) нь тэг сэргэлтийн хугацаатай нөөцлөлөөр бэлэн бус байдлыг мянга дахин бууруулна."}, {"t": "p", "s": "Процессын шинд IEC 61850-9-3 PTP-ээр ±1 мкс синхрончлол шаардлагатай: 1 мс-ийн алдаа 50 Гц-д 18° фазын алдаа үүсгэнэ.", "h": "• Процессын шинд IEC 61850-9-3 PTP-ээр ±1 мкс синхрончлол шаардлагатай: 1 мс-ийн алдаа 50 Гц-д 18° фазын алдаа үүсгэнэ."}, {"t": "p", "s": "Диспетчерийн төвтэй холбоонд Монголд IEC 60870-5-104 давамгайлдаг; GOOSE-ээр блоклолт, Ed.2-ийн test/simulation горим нь ашиглалтын аюулгүй байдал, туршилтын үр ашгийг нэмэгдүүлнэ.", "h": "• Диспетчерийн төвтэй холбоонд Монголд IEC 60870-5-104 давамгайлдаг; GOOSE-ээр блоклолт, Ed.2-ийн test/simulation горим нь ашиглалтын аюулгүй байдал, туршилтын үр ашгийг нэмэгдүүлнэ."}, {"t": "h", "l": 1, "s": "Хяналтын асуулт", "h": "Хяналтын асуулт"}, {"t": "p", "s": "Уламжлалт ба дижитал дэд станцын хоёрдогч системийн гол ялгааг нэрлэ. IEC 61850-ийн «харилцан ажиллах чадвар» гэж юу вэ?", "h": "1. Уламжлалт ба дижитал дэд станцын хоёрдогч системийн гол ялгааг нэрлэ. IEC 61850-ийн «харилцан ажиллах чадвар» гэж юу вэ?"}, {"t": "p", "s": "Станц, бэй, процессын түвшин тус бүрд ямар төхөөрөмж байрлах вэ? Станцын ба процессын шинаар ямар мессеж дамжих вэ?", "h": "2. Станц, бэй, процессын түвшин тус бүрд ямар төхөөрөмж байрлах вэ? Станцын ба процессын шинаар ямар мессеж дамжих вэ?"}, {"t": "p", "s": "Физик төхөөрөмж, логик төхөөрөмж, логик зангилаа, өгөгдлийн объект, атрибутын хамаарлыг жишээгээр тайлбарла.", "h": "3. Физик төхөөрөмж, логик төхөөрөмж, логик зангилаа, өгөгдлийн объект, атрибутын хамаарлыг жишээгээр тайлбарла."}, {"t": "p", "s": "XCBR, XSWI, CSWI, CILO, PTOC, PDIF, MMXU, TCTR, TVTR зангилааны үүргийг тайлбарла.", "h": "4. XCBR, XSWI, CSWI, CILO, PTOC, PDIF, MMXU, TCTR, TVTR зангилааны үүргийг тайлбарла."}, {"t": "p", "s": "Функциональ хязгаарлалт ST, MX, CO, SP, CF юуг заадаг вэ? Чанарын атрибут q-г захиалагч яагаад шалгах ёстой вэ?", "h": "5. Функциональ хязгаарлалт ST, MX, CO, SP, CF юуг заадаг вэ? Чанарын атрибут q-г захиалагч яагаад шалгах ёстой вэ?"}, {"t": "p", "s": "SSD, ICD, SCD, CID файлын ялгаа юу вэ? Инженерчлэлийн «дээрээс доош» дарааллыг тайлбарла.", "h": "6. SSD, ICD, SCD, CID файлын ялгаа юу вэ? Инженерчлэлийн «дээрээс доош» дарааллыг тайлбарла."}, {"t": "p", "s": "GOOSE-ийн давтан илгээлт, stNum, sqNum, TAL-ын үүргийг тайлбарла. Холбоо тасарснаас хойш хэдий хугацаанд илрэх вэ?", "h": "7. GOOSE-ийн давтан илгээлт, stNum, sqNum, TAL-ын үүргийг тайлбарла. Холбоо тасарснаас хойш хэдий хугацаанд илрэх вэ?"}, {"t": "p", "s": "9-2LE ба IEC 61869-9-ийн SV урсгалыг харьцуул. 100 Мбит/с-ийн портоор хэдэн MU-ийн урсгал дамжуулж болох вэ?", "h": "8. 9-2LE ба IEC 61869-9-ийн SV урсгалыг харьцуул. 100 Мбит/с-ийн портоор хэдэн MU-ийн урсгал дамжуулж болох вэ?"}, {"t": "p", "s": "PRP ба HSR-ийг RSTP-тэй харьцуул. Процессын шинд яагаад 1 мкс-ийн синхрончлол шаардлагатай вэ?", "h": "9. PRP ба HSR-ийг RSTP-тэй харьцуул. Процессын шинд яагаад 1 мкс-ийн синхрончлол шаардлагатай вэ?"}, {"t": "p", "s": "IEC 60870-5-104, DNP3, IEC 61850-90-2-ийг харьцуул. Test, test/blocked, simulation горимыг ямар зорилгоор хэрэглэх вэ?", "h": "10. IEC 60870-5-104, DNP3, IEC 61850-90-2-ийг харьцуул. Test, test/blocked, simulation горимыг ямар зорилгоор хэрэглэх вэ?"}, {"t": "h", "l": 1, "s": "Ном зүй", "h": "Ном зүй"}, {"t": "p", "s": "IEC 61850 (all parts). Communication networks and systems for power utility automation. Ed. 2 / 2.1. — IEC, 2011–2023.", "h": "1. IEC 61850 (all parts). Communication networks and systems for power utility automation. Ed. 2 / 2.1. — IEC, 2011–2023."}, {"t": "p", "s": "IEC 61869-9:2016. Instrument transformers — Part 9: Digital interface for instrument transformers.", "h": "2. IEC 61869-9:2016. Instrument transformers — Part 9: Digital interface for instrument transformers."}, {"t": "p", "s": "IEC/IEEE 61850-9-3:2016. Communication networks and systems for power utility automation — Part 9-3: Precision time protocol profile for power utility automation.", "h": "3. IEC/IEEE 61850-9-3:2016. Communication networks and systems for power utility automation — Part 9-3: Precision time protocol profile for power utility automation."}, {"t": "p", "s": "IEC 62439-3. Industrial communication networks — High availability automation networks — Part 3: Parallel Redundancy Protocol (PRP) and High-availability Seamless Redundancy (HSR).", "h": "4. IEC 62439-3. Industrial communication networks — High availability automation networks — Part 3: Parallel Redundancy Protocol (PRP) and High-availability Seamless Redundancy (HSR)."}, {"t": "p", "s": "IEC 60870-5-104:2006. Telecontrol equipment and systems — Part 5-104: Transmission protocols — Network access for IEC 60870-5-101 using standard transport profiles.", "h": "5. IEC 60870-5-104:2006. Telecontrol equipment and systems — Part 5-104: Transmission protocols — Network access for IEC 60870-5-101 using standard transport profiles."}, {"t": "p", "s": "IEEE Std 1815-2012. IEEE Standard for Electric Power Systems Communications — Distributed Network Protocol (DNP3).", "h": "6. IEEE Std 1815-2012. IEEE Standard for Electric Power Systems Communications — Distributed Network Protocol (DNP3)."}, {"t": "p", "s": "UCA International Users Group. Implementation Guideline for Digital Interface to Instrument Transformers Using IEC 61850-9-2 (9-2LE). — 2004.", "h": "7. UCA International Users Group. Implementation Guideline for Digital Interface to Instrument Transformers Using IEC 61850-9-2 (9-2LE). — 2004."}, {"t": "p", "s": "K.-P. Brand, V. Lohmann, W. Wimmer. Substation Automation Handbook. — Utility Automation Consulting Lohmann, 2003.", "h": "8. K.-P. Brand, V. Lohmann, W. Wimmer. Substation Automation Handbook. — Utility Automation Consulting Lohmann, 2003."}];